window.OSARIO_WORDS=[{"w":"nórdico","d":"Perteneciente o relativo a los pueblos y tierras del norte de Europa, en especial Escandinavia.","s":["escandinavo","septentrional","boreal"],"a":["meridional","austral"],"e":"Del fr. nordique, de nord, 'norte'.","x":"Bajo el hielo nórdico dormían barcos con la tripulación todavía sentada a los remos."},{"w":"brota","d":"Del verbo brotar: nacer o salir algo de la tierra, de una planta o de un cuerpo; manifestarse de golpe.","s":["surge","mana","germina","emerge","aflora"],"a":["se seca","se marchita","desaparece"],"e":"De brote, de origen germánico.","x":"De la herida vieja brota, cada luna, un hilo de savia negra."},{"w":"orilla","d":"Borde o límite de una superficie, especialmente la franja de tierra que toca el agua de un río, lago o mar.","s":["ribera","margen","borde","costa","linde"],"a":["centro","interior"],"e":"Del lat. vulg. *orella, diminutivo de ora, 'borde'.","x":"La marea dejó en la orilla una hilera de zapatos, todos del pie izquierdo."},{"w":"arder","d":"Estar en combustión, quemarse; también sentir un calor, dolor o pasión muy intensos.","s":["quemarse","abrasarse","incendiarse","consumirse"],"a":["apagarse","extinguirse","enfriarse"],"e":"Del lat. ardere.","x":"La casa ardió toda la noche y nadie escuchó gritar a los que seguían adentro."},{"w":"florecer","d":"Echar flores una planta; prosperar, desarrollarse con plenitud.","s":["brotar","abrirse","prosperar","medrar"],"a":["marchitarse","decaer","languidecer"],"e":"Del lat. florescere.","x":"En el cementerio las rosas florecen mejor sobre las tumbas más recientes."},{"w":"marchitarse","d":"Perder una planta su frescura y color; perder alguien o algo su vigor, belleza o vida.","s":["ajarse","secarse","mustiarse","languidecer"],"a":["florecer","reverdecer","revivir"],"e":"De marchito, quizá del lat. marcidus.","x":"Cada vez que ella lo tocaba, algo en él se marchitaba un poco más."},{"w":"delicadeza","d":"Cualidad de delicado: finura, suavidad, cuidado o fragilidad.","s":["finura","suavidad","tacto","sutileza","fragilidad"],"a":["tosquedad","brusquedad","rudeza"],"e":"De delicado, del lat. delicatus.","x":"Le cosió los párpados con una delicadeza casi amorosa."},{"w":"nocturno","d":"Que pertenece a la noche, sucede en ella o vive y actúa durante ella.","s":["noctámbulo","oscuro","crepuscular"],"a":["diurno"],"e":"Del lat. nocturnus.","x":"Los visitantes nocturnos nunca tocan la puerta: esperan que la abras dormido."},{"w":"armadura","d":"Conjunto de piezas de metal con que se cubría el cuerpo el guerrero; estructura o protección que sostiene o resguarda algo.","s":["coraza","arnés","blindaje","caparazón"],"a":["desnudez","vulnerabilidad"],"e":"Del lat. armatura.","x":"Al abrir la armadura no encontraron cuerpo, solo un olor dulce y una colonia de escarabajos."},{"w":"susurro","d":"Sonido suave y bajo que se hace al hablar sin voz; rumor leve del viento, el agua o las hojas.","s":["murmullo","bisbiseo","cuchicheo","rumor"],"a":["grito","alarido","estruendo"],"e":"De susurrar, del lat. susurrare, de origen onomatopéyico.","x":"El susurro venía de adentro de la pared, justo a la altura de su almohada."},{"w":"inaudible","d":"Que no se puede oír o se oye con muchísima dificultad.","s":["imperceptible","silencioso","mudo","apagado"],"a":["audible","estridente","sonoro"],"e":"Del lat. inaudibilis.","x":"Lo llamó con una voz inaudible para todos menos para los perros."},{"w":"insospechado","d":"Que no se sospecha o no se esperaba; sorprendente por lo imprevisto.","s":["inesperado","imprevisto","inopinado","sorprendente"],"a":["previsible","esperado","sabido"],"e":"De in- y sospechado, de sospechar, del lat. suspectare.","x":"El sótano escondía una profundidad insospechada, y escalones que seguían bajando."},{"w":"bosque","d":"Terreno extenso poblado de árboles y vegetación espesa.","s":["arboleda","floresta","espesura","fronda"],"a":["claro","desierto","páramo"],"e":"Del cat. u occitano bosc, de origen germánico.","x":"En ese bosque los árboles cambian de lugar mientras nadie los mira."},{"w":"nueve","d":"Número que sigue al ocho; ocho más uno.","s":[],"a":[],"e":"Del lat. novem.","x":"Eran nueve al entrar a la mina; salieron nueve, pero uno no era el mismo."},{"w":"isla","d":"Porción de tierra rodeada completamente de agua; lugar aislado o separado de su entorno.","s":["islote","ínsula","atolón","cayo"],"a":["continente"],"e":"Del lat. insula.","x":"En la isla no había nadie, pero cada mañana aparecían huellas nuevas alrededor de la carpa."},{"w":"desgranado","d":"Que ha perdido sus granos o ha sido separado en partes; dicho de palabras o sonidos, dichos uno tras otro.","s":["separado","deshecho","esparcido","disgregado"],"a":["entero","compacto"],"e":"De desgranar, de des- y grano, del lat. granum.","x":"Rezaba el rosario desgranado, cuenta a cuenta, aunque las cuentas eran dientes."},{"w":"grotesco","d":"Ridículo, extravagante o deforme hasta el punto de causar risa, rechazo o inquietud.","s":["esperpéntico","deforme","extravagante","ridículo","monstruoso"],"a":["armonioso","elegante","proporcionado"],"e":"Del it. grottesco, de grotta, 'gruta', por las pinturas halladas en ruinas.","x":"Sonreía con una mueca grotesca, como si alguien le hubiera cosido la boca hacia arriba."},{"w":"cuervos","d":"Aves grandes de plumaje negro brillante, pico fuerte y graznido ronco, asociadas a la muerte y al mal agüero.","s":["córvidos","grajos","cornejas"],"a":["palomas"],"e":"Del lat. corvus.","x":"Los cuervos ya esperaban en el alambrado antes de que el animal cayera."},{"w":"adormecido","d":"Que está medio dormido o con los sentidos entorpecidos; calmado o insensible.","s":["aletargado","somnoliento","entumecido","amodorrado"],"a":["despierto","alerta","despabilado"],"e":"De adormecer, del lat. addormiscere.","x":"Sintió la pierna adormecida y recién al rato vio que ya no la tenía."},{"w":"escombro","d":"Desecho o conjunto de restos que quedan de una construcción derribada o arruinada.","s":["ruinas","cascotes","despojos","restos","detritos"],"a":["construcción","edificio"],"e":"De origen incierto, quizá del lat. vulg. *excomborare, 'quitar estorbos'.","x":"Debajo del escombro se seguía escuchando un teléfono sonar."},{"w":"lenguas milenarias","d":"Idiomas muy antiguos, con miles de años de historia, muchas veces ya muertos o hablados por muy pocos.","s":["lenguas antiguas","idiomas muertos","lenguas arcaicas"],"a":["lenguas modernas"],"e":"De lengua (lat. lingua) y milenario (lat. millenarius, 'de mil').","x":"Hablaba en sueños en lenguas milenarias que nadie en el pueblo debería conocer."},{"w":"lánguido","d":"Flaco, débil, sin fuerzas; falto de ánimo o de energía.","s":["débil","decaído","mustio","abatido","desfallecido"],"a":["vigoroso","enérgico","vivaz"],"e":"Del lat. languidus.","x":"Una mano lánguida asomaba entre las sábanas, demasiado pálida para ser de alguien vivo."},{"w":"exangüe","d":"Desangrado, sin sangre; por extensión, sin fuerzas o muerto.","s":["desangrado","exánime","anémico","lívido","inerte"],"a":["vigoroso","rozagante"],"e":"Del lat. exsanguis.","x":"La encontraron exangüe, sin una sola herida visible."},{"w":"trance","d":"Momento crítico o decisivo; estado en que una persona queda suspendida de la conciencia ordinaria.","s":["éxtasis","arrobamiento","hipnosis","crisis","apuro"],"a":["lucidez","vigilia"],"e":"Del fr. ant. transe, de transir, 'morir', del lat. transire, 'pasar'.","x":"Durante el trance la médium habló con la voz de un nene que nadie había conocido."},{"w":"turbio","d":"Mezclado con algo que quita claridad; confuso, sospechoso o poco honesto.","s":["opaco","sucio","cenagoso","confuso","sospechoso"],"a":["claro","transparente","límpido"],"e":"Del lat. turbidus.","x":"En el agua turbia del aljibe algo se movía cuando bajaban el balde."},{"w":"agrietado","d":"Que tiene grietas o hendiduras.","s":["resquebrajado","cuarteado","rajado","hendido"],"a":["liso","intacto","entero"],"e":"De agrietar, de grieta, del lat. vulg. crepta.","x":"Sus labios agrietados sangraban cada vez que intentaba decir el nombre."},{"w":"frontera","d":"Límite que separa dos territorios o estados; línea que divide dos realidades.","s":["límite","confín","linde","borde","raya"],"a":["centro","interior"],"e":"De frontero, de fronte, 'frente', del lat. frons.","x":"Del otro lado de la frontera los muertos todavía usan los nombres de los vivos."},{"w":"franqueza","d":"Sinceridad, claridad y llaneza al hablar o actuar.","s":["sinceridad","honestidad","llaneza","claridad"],"a":["hipocresía","doblez","disimulo"],"e":"De franco, del germánico frank, 'libre'.","x":"Le dijo con franqueza cuánto tiempo le quedaba, y después se rio."},{"w":"madeja","d":"Hilo recogido en vueltas iguales; conjunto enredado de cosas o asuntos.","s":["ovillo","enredo","maraña","lío"],"a":[],"e":"Del lat. mataxa, 'cordón'.","x":"Del cajón sacó una madeja de cabello, trenzado por manos que ya no existían."},{"w":"remata","d":"Del verbo rematar: acabar con algo o alguien que está a punto de morir; dar fin a una cosa.","s":["ultima","acaba","concluye","finaliza"],"a":["empieza","inicia"],"e":"De re- y matar.","x":"El cazador se acerca despacio y remata al ciervo con una ternura que da miedo."},{"w":"gesto","d":"Movimiento del rostro, las manos o el cuerpo que expresa algo; acto que tiene un significado.","s":["ademán","mueca","seña","expresión","actitud"],"a":[],"e":"Del lat. gestus.","x":"Hizo un gesto con la mano y todas las velas se apagaron, menos la de él."},{"w":"preciso","d":"Exacto, puntual, sin errores; también necesario o indispensable.","s":["exacto","justo","riguroso","necesario"],"a":["impreciso","vago","aproximado"],"e":"Del lat. praecisus, 'cortado'.","x":"El corte fue preciso, casi quirúrgico; nadie sabía que ella había estudiado costura."},{"w":"gotea","d":"Del verbo gotear: caer un líquido gota a gota.","s":["chorrea","destila","rezuma","escurre"],"a":[],"e":"De gota, del lat. gutta.","x":"Algo gotea desde el techo del altillo, y no llovió en toda la semana."},{"w":"plata","d":"Metal precioso blanco y brillante; color semejante a ese metal. En el Río de la Plata, también dinero.","s":["argento","dinero","guita"],"a":[],"e":"Del lat. vulg. *plattus, 'plano', por las láminas de metal.","x":"Las balas de plata eran de su abuela; nadie le había dicho para qué servían."},{"w":"daga","d":"Arma blanca corta, de hoja ancha y punzante.","s":["puñal","estilete","cuchillo","facón"],"a":[],"e":"De origen incierto.","x":"La daga seguía caliente cuando la sacó del pecho del retrato."},{"w":"harapos","d":"Prendas viejas, rotas y sucias.","s":["andrajos","jirones","trapos","guiñapos"],"a":["galas","atuendo"],"e":"De origen incierto.","x":"El espantapájaros llevaba los harapos del hombre que desapareció en la cosecha."},{"w":"apatía","d":"Falta de interés, de emoción o de energía; indiferencia.","s":["desgana","indiferencia","abulia","desidia","desinterés"],"a":["entusiasmo","pasión","interés"],"e":"Del gr. apátheia, 'sin padecimiento'.","x":"Miró arder la casa con una apatía que asustó más que el fuego."},{"w":"tembloroso","d":"Que tiembla o se agita con movimientos pequeños y repetidos.","s":["trémulo","vacilante","agitado","estremecido"],"a":["firme","sereno","quieto"],"e":"De temblor, de temblar, del lat. vulg. *tremulare.","x":"Con la mano temblorosa giró el picaporte, y del otro lado alguien lo giró también."},{"w":"arrebatar","d":"Quitar algo con violencia y rapidez; atraer intensamente o arrastrar.","s":["arrancar","quitar","despojar","usurpar","cautivar"],"a":["devolver","restituir","dar"],"e":"De a- y rebato, 'ataque repentino'.","x":"La corriente le arrebató al nene de los brazos y nunca devolvió el cuerpo."},{"w":"trovador","d":"Poeta y músico medieval que componía y cantaba versos, sobre todo de amor; por extensión, poeta.","s":["juglar","bardo","poeta","cantor","rapsoda"],"a":[],"e":"Del occitano trobador, de trobar, 'componer versos'.","x":"El trovador cantaba la misma canción en cada pueblo, y en cada pueblo desaparecía una chica."},{"w":"resquicio","d":"Abertura estrecha entre el quicio y la puerta, o cualquier hendidura pequeña; posibilidad mínima.","s":["rendija","hendidura","grieta","ranura","intersticio"],"a":[],"e":"De re- y quicio.","x":"Por el resquicio de la puerta asomaba un ojo que no parpadeaba."},{"w":"copa","d":"Vaso con pie para beber; parte alta y ramificada de un árbol.","s":["cáliz","vaso","trofeo","fronda"],"a":["raíz","pie"],"e":"Del lat. cuppa.","x":"Brindaron con la copa de vino y nadie notó que el de ella tenía otro color."},{"w":"ajena","d":"Que pertenece a otra persona; extraña, distante o que no corresponde.","s":["extraña","foránea","impropia","distante"],"a":["propia","personal"],"e":"Del lat. alienus.","x":"Se miró al espejo y la cara que le devolvió era ajena, aunque sonreía como ella."},{"w":"cáliz","d":"Copa sagrada en la que se consagra el vino en la misa; en botánica, cubierta exterior de la flor; figuradamente, sufrimiento.","s":["copa","grial","vaso sagrado"],"a":[],"e":"Del lat. calix.","x":"El cura levantó el cáliz y de adentro subió un olor a hierro."},{"w":"filo","d":"Borde agudo y cortante de un instrumento; línea o punto límite entre dos cosas.","s":["corte","borde","arista","canto","límite"],"a":["lomo","romo"],"e":"Del lat. filum, 'hilo'.","x":"Pasó el dedo por el filo y sonrió al ver que todavía cortaba."},{"w":"escalofrío","d":"Sensación de frío repentino con temblor, causada por miedo, fiebre o emoción.","s":["estremecimiento","temblor","repelús","espeluzno"],"a":["calor","sosiego"],"e":"De calofrío ('calor y frío'), cruzado con escalentar.","x":"Le corrió un escalofrío cuando escuchó su propio nombre desde el pozo."},{"w":"vaivén","d":"Movimiento de un cuerpo que va y viene alternadamente; inestabilidad, cambios.","s":["balanceo","oscilación","bamboleo","fluctuación"],"a":["quietud","estabilidad"],"e":"De va y viene.","x":"El vaivén de la mecedora seguía aunque la abuela llevaba un año enterrada."},{"w":"desparramado","d":"Esparcido o extendido sin orden por distintos lugares.","s":["esparcido","diseminado","disperso","derramado"],"a":["reunido","amontonado","ordenado"],"e":"De desparramar, cruce de esparcir y derramar.","x":"Lo encontraron desparramado por todo el living, como si hubiera estallado desde adentro."},{"w":"sepia","d":"Color marrón rojizo propio de las fotografías antiguas; también molusco parecido al calamar que suelta tinta.","s":["ocre","pardo","jibia"],"a":[],"e":"Del lat. sepia, y este del gr. sēpía, 'jibia'.","x":"En la foto sepia de 1910 estaba ella, con la misma edad que tiene hoy."},{"w":"desproporcionado","d":"Que no guarda la proporción debida entre sus partes o con otra cosa; excesivo.","s":["deforme","descomunal","excesivo","asimétrico","desmedido"],"a":["proporcionado","armónico","mesurado"],"e":"De des- y proporcionado.","x":"Tenía los brazos desproporcionados, tan largos que arrastraba los nudillos por el piso."},{"w":"pensativo","d":"Que está absorto en sus pensamientos.","s":["meditabundo","absorto","reflexivo","ensimismado"],"a":["distraído","despreocupado"],"e":"De pensar, del lat. pensare.","x":"El muerto tenía una expresión pensativa, como si todavía estuviera calculando algo."},{"w":"parálisis","d":"Pérdida total o parcial de la capacidad de movimiento de una parte del cuerpo; inmovilidad.","s":["inmovilidad","paralización","agarrotamiento","estancamiento"],"a":["movimiento","actividad"],"e":"Del gr. parálysis, 'aflojamiento'.","x":"En la parálisis del sueño la vio sentada al borde de la cama, peinándose."},{"w":"remoto","d":"Muy lejano en el espacio o en el tiempo; poco probable.","s":["lejano","distante","apartado","improbable"],"a":["cercano","próximo","inmediato"],"e":"Del lat. remotus.","x":"En un pueblo remoto todavía entierran a los muertos boca abajo."},{"w":"inmenso","d":"Tan grande que no se puede medir; enorme.","s":["enorme","vasto","colosal","infinito","descomunal"],"a":["diminuto","minúsculo","limitado"],"e":"Del lat. immensus, 'no medido'.","x":"Algo inmenso respiraba debajo del lago congelado."},{"w":"culpa","d":"Responsabilidad por un daño o falta; sentimiento de haber obrado mal.","s":["falta","remordimiento","responsabilidad","cargo"],"a":["inocencia","disculpa"],"e":"Del lat. culpa.","x":"La culpa la despertaba a las tres de la mañana con la voz de su hermano."},{"w":"abatirse","d":"Precipitarse o caer algo sobre alguien o algo; perder el ánimo o las fuerzas.","s":["precipitarse","caer","desplomarse","decaer","desanimarse"],"a":["alzarse","animarse","levantarse"],"e":"Del lat. vulg. *abbattuere, 'derribar'.","x":"La bandada se abatió sobre el campo y en minutos no quedó nada vivo."},{"w":"asfixia","d":"Suspensión de la respiración por falta de aire; sensación de agobio u opresión.","s":["ahogo","sofocación","opresión","estrangulamiento"],"a":["respiración","alivio","desahogo"],"e":"Del gr. asphyxía, 'falta de pulso'.","x":"La asfixia llegó despacio, mientras la tierra seguía cayendo sobre el cajón."},{"w":"desamparado","d":"Que está sin ayuda, protección ni amparo.","s":["abandonado","desvalido","indefenso","huérfano","solo"],"a":["amparado","protegido","acompañado"],"e":"De des- y amparar, del lat. vulg. *anteparare.","x":"El nene desamparado pedía que alguien le abriera, pero llamaba desde adentro del ropero."},{"w":"desdén","d":"Indiferencia y desprecio hacia algo o alguien.","s":["desprecio","menosprecio","altivez","indiferencia"],"a":["aprecio","estima","consideración"],"e":"De desdeñar, del lat. dedignari.","x":"La miró con desdén mientras ella se hundía en el barro."},{"w":"vejez","d":"Última etapa de la vida; cualidad de viejo.","s":["ancianidad","senectud","longevidad","decrepitud"],"a":["juventud","niñez","lozanía"],"e":"De viejo, del lat. vetulus.","x":"La vejez le llegó en una sola noche, la noche que abrió el cofre."},{"w":"soledad","d":"Falta de compañía; estado de quien está solo; lugar desierto.","s":["aislamiento","abandono","retiro","desamparo"],"a":["compañía","multitud"],"e":"Del lat. solitas, -atis.","x":"La soledad en la casa tenía pasos, y eran cada vez más cerca."},{"w":"carencia","d":"Falta o privación de algo necesario.","s":["falta","escasez","privación","ausencia","déficit"],"a":["abundancia","exceso","plenitud"],"e":"Del lat. carentia.","x":"Lo que más asustaba de la muñeca era la carencia de ojos."},{"w":"insignificante","d":"Que no tiene importancia o valor; muy pequeño.","s":["irrelevante","nimio","ínfimo","trivial","minúsculo"],"a":["importante","significativo","trascendente"],"e":"De in- y significante, del lat. significans.","x":"Era un corte insignificante, pero nunca dejó de sangrar."},{"w":"insondable","d":"Que no se puede sondear o llegar al fondo; imposible de conocer o comprender.","s":["abismal","impenetrable","inescrutable","profundo","inexplicable"],"a":["superficial","comprensible"],"e":"De in- y sondable, de sondar, del fr. sonder.","x":"Tenía una tristeza insondable en los ojos, y algo moviéndose al fondo."},{"w":"abismo","d":"Profundidad muy grande y peligrosa; distancia o diferencia enorme.","s":["precipicio","sima","barranco","vacío","despeñadero"],"a":["cima","cumbre"],"e":"Del lat. vulg. *abyssimus, superlativo de abyssus.","x":"Si mirás mucho tiempo al abismo, empieza a conocer tu nombre."},{"w":"anhelo","d":"Deseo intenso de conseguir algo.","s":["ansia","deseo","afán","aspiración","añoranza"],"a":["desinterés","indiferencia","hastío"],"e":"De anhelar, del lat. anhelare, 'jadear'.","x":"Su único anhelo era volver a escuchar el corazón que guardaba en el frasco."},{"w":"desilusión","d":"Pérdida de una ilusión o esperanza; decepción.","s":["decepción","desengaño","desencanto","chasco"],"a":["ilusión","esperanza","entusiasmo"],"e":"De des- e ilusión.","x":"La desilusión del fantasma fue ver que nadie en la casa lo extrañaba."},{"w":"ridículo","d":"Que mueve a risa por su rareza o extravagancia; escaso, insignificante.","s":["grotesco","absurdo","risible","irrisorio"],"a":["serio","digno","respetable"],"e":"Del lat. ridiculus.","x":"Murió de una forma tan ridícula que en el velorio nadie podía parar de reír."},{"w":"indefenso","d":"Que carece de medios para defenderse.","s":["desvalido","desprotegido","vulnerable","inerme"],"a":["protegido","armado","defendido"],"e":"De in- y defenso, del lat. defensus.","x":"Lo más indefenso de la casa no era el bebé: era lo que lo cuidaba."},{"w":"desdicha","d":"Desgracia, mala suerte; pobreza o miseria extrema.","s":["desgracia","infortunio","desventura","adversidad"],"a":["dicha","felicidad","fortuna"],"e":"De des- y dicha, del lat. dicta, 'cosas dichas'.","x":"La desdicha caminaba detrás de la familia como un perro fiel."},{"w":"fracasado","d":"Que no ha logrado lo que pretendía; persona desacreditada por sus fracasos.","s":["frustrado","malogrado","perdedor","fallido"],"a":["exitoso","triunfador","logrado"],"e":"De fracasar, del it. fracassare, 'romper con estrépito'.","x":"El fracasado se fue a dormir al cementerio, donde nadie lo comparaba con nadie."},{"w":"intenso","d":"Que se manifiesta con mucha fuerza, energía o profundidad.","s":["fuerte","profundo","agudo","vehemente","acentuado"],"a":["débil","leve","suave"],"e":"Del lat. intensus.","x":"Un dolor intenso le recorrió el brazo justo antes de que la mano dejara de ser suya."},{"w":"irrevocable","d":"Que no se puede anular, revocar ni deshacer.","s":["definitivo","inapelable","irreversible","firme"],"a":["revocable","provisional","reversible"],"e":"Del lat. irrevocabilis.","x":"Firmó con sangre, y la firma era irrevocable."},{"w":"insalvable","d":"Que no se puede salvar, superar o evitar.","s":["infranqueable","insuperable","invencible","imposible"],"a":["superable","salvable"],"e":"De in- y salvable, de salvar, del lat. salvare.","x":"Entre los vivos y ella había una distancia insalvable de dos metros de tierra."},{"w":"opresión","d":"Acción de oprimir; sensación de molestia o ahogo; dominio abusivo.","s":["tiranía","yugo","sometimiento","ahogo","agobio"],"a":["libertad","liberación","alivio"],"e":"Del lat. oppressio.","x":"Sentía una opresión en el pecho, como si alguien se hubiera sentado encima mientras dormía."},{"w":"liberación","d":"Acción de liberar o liberarse; alivio de una carga, obligación o encierro.","s":["emancipación","libertad","redención","alivio"],"a":["opresión","encierro","cautiverio"],"e":"Del lat. liberatio.","x":"La muerte llegó como una liberación, aunque lo que vino después no lo fue."},{"w":"impedimento","d":"Obstáculo o estorbo que dificulta o imposibilita algo.","s":["obstáculo","traba","estorbo","barrera","inconveniente"],"a":["facilidad","ayuda"],"e":"Del lat. impedimentum.","x":"El único impedimento para casarse era que el novio llevaba diez años muerto."},{"w":"vacilación","d":"Duda o indecisión; movimiento indeciso o poco firme.","s":["duda","titubeo","indecisión","vaivén"],"a":["firmeza","decisión","seguridad"],"e":"Del lat. vacillatio.","x":"Tras un segundo de vacilación, bajó el cuchillo."},{"w":"atormentado","d":"Que sufre tormento, angustia o dolor intenso.","s":["torturado","afligido","angustiado","acongojado","martirizado"],"a":["tranquilo","sereno","apacible"],"e":"De atormentar, de tormento, del lat. tormentum.","x":"El espíritu atormentado solo pedía que alguien terminara de leer su carta."},{"w":"imprescindible","d":"Que no se puede prescindir de ello; absolutamente necesario.","s":["indispensable","esencial","necesario","vital"],"a":["prescindible","superfluo","innecesario"],"e":"De in- y prescindible, del lat. praescindere.","x":"Para el ritual, lo imprescindible era la sangre de alguien que te amara."},{"w":"mirada","d":"Acción de mirar; modo de mirar; expresión de los ojos.","s":["vistazo","ojeada","ojos","visión"],"a":[],"e":"De mirar, del lat. mirari, 'admirarse'.","x":"Sintió la mirada en la nuca, aunque en la casa no quedaba nadie con ojos."},{"w":"sequedad","d":"Falta de humedad; aspereza o dureza en el trato.","s":["aridez","resequedad","aspereza","frialdad"],"a":["humedad","amabilidad"],"e":"De seco, del lat. siccus.","x":"La sequedad de la piel del muerto crujía como papel al tocarla."},{"w":"abstracto","d":"Que no es concreto; que expresa una cualidad separada de su objeto; difícil de entender.","s":["teórico","conceptual","inmaterial","vago"],"a":["concreto","tangible","real"],"e":"Del lat. abstractus, 'separado'.","x":"Su miedo empezó siendo abstracto, hasta que la cosa del sueño apareció en la cocina."},{"w":"enloquecido","d":"Que ha perdido la razón; muy alterado o fuera de sí.","s":["demente","trastornado","desquiciado","frenético","loco"],"a":["cuerdo","sereno","lúcido"],"e":"De enloquecer, de loco, de origen incierto.","x":"El perro corría enloquecido alrededor de la tumba recién cavada."},{"w":"serpiente","d":"Reptil sin patas, de cuerpo alargado y escamoso; símbolo de la tentación y la traición.","s":["culebra","víbora","sierpe","ofidio"],"a":[],"e":"Del lat. serpens, -entis, 'que se arrastra'.","x":"La serpiente salió de la boca del santo, despacio, como si conociera el camino."},{"w":"cautela","d":"Precaución y reserva con que se actúa para evitar un peligro o engaño.","s":["precaución","prudencia","cuidado","reserva","sigilo"],"a":["imprudencia","descuido","temeridad"],"e":"Del lat. cautela.","x":"Abrió el cajón con cautela, porque los dedos del otro lado ya habían aprendido."},{"w":"lágrimas","d":"Gotas de líquido que segregan los ojos, sobre todo al llorar.","s":["llanto","lloro","gotas"],"a":["risa"],"e":"Del lat. lacrima.","x":"Las lágrimas de la estatua eran rojas y olían a óxido."},{"w":"tenazas","d":"Herramienta de metal formada por dos brazos articulados que sirve para agarrar, arrancar o cortar.","s":["pinzas","alicates","tenacillas"],"a":[],"e":"Del lat. tenaces, pl. de tenax, 'que agarra'.","x":"Guardaba las tenazas al lado del sillón de dentista, y no era dentista."},{"w":"garfio","d":"Gancho de hierro, curvo y puntiagudo, para agarrar o colgar algo.","s":["gancho","arpón","uña"],"a":[],"e":"Del lat. vulg. *graphium, 'punzón'.","x":"En el galpón colgaban del garfio cosas que no eran exactamente corderos."},{"w":"trampas","d":"Artefactos para cazar animales; engaños para perjudicar a alguien.","s":["cepos","lazos","emboscadas","ardides","artimañas"],"a":[],"e":"De origen onomatopéyico.","x":"Las trampas del monte amanecían cerradas, pero vacías y con sangre."},{"w":"osos","d":"Mamíferos grandes y corpulentos, de pelaje espeso y garras fuertes.","s":["úrsidos"],"a":[],"e":"Del lat. ursus.","x":"Los osos no se acercaban a esa cabaña, y eso era lo más inquietante."},{"w":"morder","d":"Clavar los dientes en algo; desgastar o corroer lentamente.","s":["dentellear","mordisquear","roer","clavar"],"a":["soltar"],"e":"Del lat. mordere.","x":"El nene empezó a morder a los otros chicos el mismo día que volvió del bosque."},{"w":"labios","d":"Cada uno de los bordes carnosos y móviles que rodean la boca.","s":["boca","belfos","comisuras"],"a":[],"e":"Del lat. labium.","x":"Tenía los labios cosidos con hilo negro, y aun así tarareaba."},{"w":"chillidos","d":"Gritos agudos y desagradables, de personas o animales.","s":["alaridos","gritos","chirridos","aullidos"],"a":["silencio","susurros"],"e":"De chillar, de origen onomatopéyico.","x":"Los chillidos del chiquero pararon de golpe, y eso fue peor."},{"w":"malsano","d":"Dañino para la salud física o moral; enfermizo.","s":["insano","nocivo","morboso","enfermizo","dañino"],"a":["sano","saludable"],"e":"De mal y sano.","x":"Había una curiosidad malsana en su manera de mirar los accidentes."},{"w":"amarillento","d":"Que tira a amarillo; de color amarillo pálido, como algo viejo o enfermo.","s":["ambarino","cetrino","pálido","descolorido"],"a":[],"e":"De amarillo, del lat. tardío amarellus.","x":"Tenía las uñas largas y amarillentas, y las tamborileaba sobre el ataúd."},{"w":"radioactivo","d":"Que emite radiactividad; por extensión, peligroso o tóxico.","s":["radiactivo","contaminado","tóxico"],"a":["inocuo"],"e":"De radio y activo.","x":"El pueblo quedó radioactivo, pero las luces de las casas se siguen prendiendo cada noche."},{"w":"perverso","d":"Que hace el mal a sabiendas y con gusto; que corrompe.","s":["malvado","depravado","maligno","cruel","retorcido"],"a":["bondadoso","virtuoso","noble"],"e":"Del lat. perversus, 'dado vuelta'.","x":"Tenía un sentido del humor perverso: le gustaba enterrar a la gente con los ojos abiertos."},{"w":"rencor","d":"Resentimiento persistente y arraigado hacia alguien por una ofensa.","s":["resentimiento","odio","encono","inquina","animadversión"],"a":["perdón","afecto","olvido"],"e":"Del lat. rancor, 'rancio'.","x":"El rencor lo mantuvo vivo mucho después de que el corazón se le detuviera."},{"w":"desnudez","d":"Estado de desnudo; falta de adornos o de protección.","s":["desabrigo","despojo","descubrimiento"],"a":["abrigo","vestimenta"],"e":"De desnudo, del lat. nudus.","x":"La desnudez del árbol en invierno dejaba ver los nidos, y lo que había adentro."},{"w":"malhumor","d":"Estado de ánimo irritado, enojado o desagradable.","s":["enojo","irritación","mal genio","fastidio"],"a":["buen humor","alegría"],"e":"De mal y humor, del lat. humor, 'líquido', por los humores del cuerpo.","x":"El malhumor de la vieja del fondo se notaba en cómo crujía el piso de arriba."},{"w":"temible","d":"Digno o capaz de causar temor.","s":["terrible","espantoso","amenazador","aterrador","peligroso"],"a":["inofensivo","inocuo"],"e":"De temer, del lat. timere.","x":"Lo temible no era su fuerza, sino la paciencia con que esperaba."},{"w":"grieta","d":"Abertura larga y estrecha que se forma en una superficie.","s":["hendidura","fisura","raja","resquicio"],"a":[],"e":"Del lat. vulg. crepta, de crepitare, 'crujir'.","x":"Por la grieta de la pared salía un aire tibio, como de una boca."},{"w":"volcán","d":"Abertura en la tierra por donde salen lava, gases y ceniza; persona o pasión impetuosa.","s":["cráter","montaña de fuego"],"a":[],"e":"Del lat. Vulcanus, dios del fuego.","x":"Al pie del volcán, los del pueblo dejaban ofrendas que no eran frutas."},{"w":"estatua","d":"Figura de bulto, esculpida o modelada, que representa a una persona, animal o cosa.","s":["escultura","efigie","figura","talla","imagen"],"a":[],"e":"Del lat. statua.","x":"Cada mañana la estatua estaba un poco más cerca de la ventana del dormitorio."},{"w":"erupción","d":"Salida violenta de materia del interior de la tierra; aparición brusca de granos o manchas en la piel.","s":["estallido","explosión","brote","eclosión"],"a":[],"e":"Del lat. eruptio.","x":"La erupción en la piel tenía forma de letras, y formaban un nombre."},{"w":"gigantesco","d":"Enorme, de tamaño desmesurado.","s":["colosal","descomunal","enorme","ciclópeo","titánico"],"a":["diminuto","minúsculo","enano"],"e":"De gigante, del lat. gigas, -antis.","x":"Una sombra gigantesca cruzó el campo, pero el cielo estaba despejado."},{"w":"universo","d":"Conjunto de todo lo que existe; mundo, ámbito.","s":["cosmos","mundo","creación","infinito"],"a":["nada"],"e":"Del lat. universum.","x":"En algún rincón del universo, algo escucha cuando rezás."},{"w":"diminuto","d":"Excesivamente pequeño.","s":["minúsculo","ínfimo","menudo","microscópico"],"a":["enorme","gigantesco","inmenso"],"e":"Del lat. diminutus.","x":"Encontró unos dientes diminutos en el fondo del cajón, como de bebé, pero muchos más."},{"w":"minúsculo","d":"De muy pequeñas dimensiones o de poca importancia.","s":["diminuto","ínfimo","microscópico","insignificante"],"a":["mayúsculo","enorme"],"e":"Del lat. minusculus.","x":"Un agujero minúsculo en la pared, del tamaño exacto de un ojo."},{"w":"abrupto","d":"Escarpado, de pendiente muy fuerte; brusco, repentino o áspero.","s":["escarpado","brusco","repentino","áspero","súbito"],"a":["suave","llano","gradual"],"e":"Del lat. abruptus, 'cortado'.","x":"El camino terminaba de forma abrupta, y del borde colgaba una soga."},{"w":"sacudir","d":"Mover algo violentamente de un lado a otro; conmover o alterar profundamente.","s":["agitar","zarandear","estremecer","remecer","conmocionar"],"a":["aquietar","calmar"],"e":"Del lat. succutere.","x":"La sacudió hasta que dejó de llorar, y después siguió sacudiéndola."},{"w":"ansiedad","d":"Estado de agitación, inquietud o angustia intensa.","s":["angustia","inquietud","desasosiego","zozobra","nerviosismo"],"a":["calma","serenidad","sosiego"],"e":"Del lat. anxietas.","x":"La ansiedad le susurraba que alguien estaba debajo de la cama, y esta vez tenía razón."},{"w":"vigilante","d":"Que vigila; persona encargada de custodiar algo.","s":["guardián","centinela","custodio","atento","alerta"],"a":["descuidado","distraído"],"e":"De vigilar, del lat. vigilare.","x":"El vigilante del cementerio cuenta las tumbas cada noche, y a veces le sobra una."},{"w":"ciego","d":"Privado del sentido de la vista; ofuscado, que no ve lo evidente.","s":["invidente","ofuscado","obcecado"],"a":["vidente"],"e":"Del lat. caecus.","x":"El ciego del andén siempre sabía quién iba a morir esa semana."},{"w":"atravesado","d":"Que ha sido traspasado de un lado a otro; puesto en sentido transversal; malintencionado.","s":["traspasado","perforado","cruzado","ensartado"],"a":[],"e":"De atravesar, de través, del lat. transversus.","x":"Lo encontraron atravesado por una estaca, pero seguía sonriendo."},{"w":"hambre","d":"Gana y necesidad de comer; deseo ardiente de algo.","s":["apetito","ansia","avidez","inanición"],"a":["saciedad","hartazgo"],"e":"Del lat. vulg. famen, -inis.","x":"El hambre de los que bajaban del cerro no se calmaba con pan."},{"w":"ratas","d":"Roedores de cola larga y pelada, asociados a la suciedad y la peste.","s":["roedores","ratones","pericotes"],"a":[],"e":"De origen incierto, quizá onomatopéyico.","x":"Las ratas abandonaron la casa una semana antes de que la familia se mudara."},{"w":"osamenta","d":"Esqueleto o conjunto de huesos de un cuerpo.","s":["esqueleto","armazón","huesos","huesamenta"],"a":[],"e":"Del lat. ossamenta, de os, ossis, 'hueso'.","x":"La osamenta de la vaca brillaba bajo la luna, y en el cráneo había algo vivo."},{"w":"aroma","d":"Olor agradable y penetrante.","s":["perfume","fragancia","esencia","olor"],"a":["hedor","pestilencia","fetidez"],"e":"Del lat. aroma, y este del gr. árōma.","x":"El aroma a jazmín llenaba el cuarto cada vez que la muerta pasaba."},{"w":"porfiado","d":"Obstinado, terco en sus ideas o acciones.","s":["terco","obstinado","testarudo","tozudo","pertinaz"],"a":["dócil","flexible","razonable"],"e":"De porfiar, de porfía, del lat. perfidia.","x":"El muerto era porfiado y volvía a sentarse a la mesa cada domingo."},{"w":"pétalos secos","d":"Hojas de la flor que han perdido la humedad y el color, frágiles y quebradizas.","s":["flores marchitas","pétalos mustios"],"a":["pétalos frescos"],"e":"De pétalo (gr. pétalon, 'hoja') y seco (lat. siccus).","x":"Entre las páginas del diario había pétalos secos y una uña."},{"w":"lápida","d":"Piedra plana con una inscripción, que suele cubrir o señalar una tumba.","s":["losa","estela","tumba","sepultura"],"a":[],"e":"Del lat. lapis, lapidis, 'piedra'.","x":"En la lápida estaba tallado su nombre, y la fecha era de mañana."},{"w":"plumaje","d":"Conjunto de plumas que cubren el cuerpo de un ave.","s":["plumas","penacho"],"a":[],"e":"Del fr. plumage.","x":"El plumaje del cuervo tenía reflejos rojos cuando se posaba sobre la cama del enfermo."},{"w":"apasionado","d":"Que siente o muestra pasión intensa; poseído de una emoción vehemente.","s":["ardiente","fogoso","vehemente","ferviente","entusiasta"],"a":["frío","indiferente","apático"],"e":"De apasionar, de pasión, del lat. passio.","x":"Fue un amor apasionado, de esos que terminan con alguien enterrado en el jardín."},{"w":"increíble","d":"Que no puede creerse o es muy difícil de creer; extraordinario.","s":["inverosímil","asombroso","inaudito","extraordinario"],"a":["creíble","verosímil","normal"],"e":"Del lat. incredibilis.","x":"Lo increíble no era que hubiera vuelto, sino que nadie más lo notara."},{"w":"chacales","d":"Mamíferos carnívoros parecidos al lobo, que se alimentan sobre todo de carroña.","s":["cánidos","carroñeros"],"a":[],"e":"Del turco çakal, y este del persa šagāl.","x":"Los chacales rondaban el campamento esperando al más débil."},{"w":"melancolía","d":"Tristeza profunda, vaga y permanente, sin causa clara.","s":["tristeza","nostalgia","morriña","pesadumbre","abatimiento"],"a":["alegría","euforia","júbilo"],"e":"Del lat. melancholia, y este del gr., 'bilis negra'.","x":"La melancolía de la casa se pegaba a la ropa como el olor a humedad."},{"w":"irresistible","d":"Que no se puede resistir; muy atractivo o tentador.","s":["tentador","cautivador","seductor","arrollador"],"a":["resistible","repulsivo"],"e":"De in- y resistible, del lat. resistere.","x":"Sentía un deseo irresistible de bajar al sótano a medianoche."},{"w":"misterio","d":"Cosa secreta o inexplicable; lo que no se puede comprender.","s":["enigma","secreto","incógnita","arcano"],"a":["evidencia","claridad"],"e":"Del lat. mysterium, del gr. mystḗrion.","x":"El misterio del pueblo era por qué nunca nadie llegaba a viejo."},{"w":"patético","d":"Que conmueve profundamente o produce dolor, tristeza o lástima.","s":["conmovedor","lastimoso","penoso","triste","ridículo"],"a":["alegre","digno"],"e":"Del gr. pathētikós, 'que padece'.","x":"Su intento de pedir perdón fue patético; igual lo enterró vivo."},{"w":"inválido","d":"Que no puede moverse o valerse por sí mismo; que no tiene validez.","s":["impedido","lisiado","nulo"],"a":["válido","útil"],"e":"Del lat. invalidus.","x":"El viejo inválido del primer piso caminaba de noche por los pasillos."},{"w":"agobio","d":"Sensación de opresión, cansancio extremo o angustia.","s":["opresión","angustia","sofoco","fatiga"],"a":["alivio","desahogo","descanso"],"e":"De agobiar, de origen incierto.","x":"El agobio de la casa vacía era peor que cualquier fantasma."},{"w":"pavor","d":"Temor muy intenso, con sobresalto.","s":["terror","pánico","espanto","horror","miedo"],"a":["valor","serenidad","calma"],"e":"Del lat. pavor.","x":"Sintió pavor al ver que la sombra no seguía sus movimientos."},{"w":"horror","d":"Miedo intenso causado por algo terrible o repugnante.","s":["espanto","terror","pavor","pánico"],"a":["placer","agrado","calma"],"e":"Del lat. horror.","x":"El horror no gritaba: tocaba despacio la puerta cada noche."},{"w":"atroz","d":"Cruel, inhumano; enorme, desmesurado.","s":["cruel","brutal","espantoso","horrible","monstruoso"],"a":["humano","leve","benigno"],"e":"Del lat. atrox, -ocis.","x":"Murió de una forma atroz, y lo peor fue que sonrió hasta el final."},{"w":"desterrado","d":"Expulsado de su tierra o de un lugar.","s":["exiliado","proscrito","expatriado","deportado"],"a":["repatriado","acogido"],"e":"De desterrar, de des- y tierra.","x":"Las almas desterradas vagan por la costa buscando un cuerpo que las acepte."},{"w":"despatarrado","d":"Con las piernas muy abiertas o extendido de cualquier manera.","s":["abierto","tendido","desparramado","despanzurrado"],"a":["recogido","compuesto"],"e":"De despatarrar, de pata.","x":"La muñeca quedó despatarrada en la escalera, con la cabeza girada al revés."},{"w":"derramatinta","d":"Palabra poco común: quien derrama tinta, es decir, escribe en exceso o con desborde; escritor torrencial.","s":["escritor","escribidor","emborronador","plumífero"],"a":[],"e":"Compuesto de derramar y tinta.","x":"El derramatinta escribía hasta que la tinta se le terminaba, y después seguía con otra cosa roja."},{"w":"tartamudo","d":"Que habla con pronunciación entrecortada, repitiendo sílabas o sonidos.","s":["balbuciente","tartajoso","gago","balbuceante"],"a":["elocuente","fluido"],"e":"De tartamudear, de origen onomatopéyico.","x":"El tartamudo era el único que no tropezaba al rezar en latín."},{"w":"pergamino","d":"Piel de animal curtida y preparada para escribir sobre ella; documento escrito en ese material.","s":["vitela","códice","manuscrito","documento"],"a":[],"e":"Del lat. pergaminum, de Pérgamo, ciudad donde se perfeccionó.","x":"El pergamino tenía poros, y en el borde un tatuaje."},{"w":"cuencas","d":"Cavidades donde se alojan los ojos; también territorios cuyas aguas van a un mismo río o mar.","s":["órbitas","cavidades","huecos","valles"],"a":[],"e":"Del lat. concha.","x":"Lo miraba desde unas cuencas vacías, y aun así lo seguía con la cabeza."},{"w":"momificado","d":"Convertido en momia; desecado y conservado a lo largo del tiempo.","s":["embalsamado","disecado","acartonado","apergaminado"],"a":["fresco","putrefacto"],"e":"De momificar, de momia, del ár. mūmiyā, 'betún'.","x":"El gato momificado apareció detrás de la pared, en posición de rezo."},{"w":"ancestral","d":"Relativo a los antepasados; muy antiguo o tradicional.","s":["atávico","antiquísimo","primitivo","inmemorial"],"a":["moderno","reciente","actual"],"e":"Del fr. ancestral, de ancestre, 'antepasado'.","x":"Un miedo ancestral lo paralizó al escuchar el tambor en el monte."},{"w":"máscara","d":"Figura que cubre la cara para ocultarla o disfrazarla; apariencia engañosa.","s":["careta","antifaz","disfraz","fachada"],"a":["rostro","cara"],"e":"Del it. maschera, de origen incierto.","x":"Debajo de la máscara había otra máscara, y debajo de esa, nada."},{"w":"mandíbula","d":"Cada una de las dos piezas óseas que forman la boca y en las que se insertan los dientes.","s":["quijada","maxilar","mentón"],"a":[],"e":"Del lat. mandibula, de mandere, 'masticar'.","x":"La mandíbula se le desencajó al gritar, y ya no pudo cerrarla."},{"w":"encías","d":"Carne que cubre la base de los dientes.","s":[],"a":[],"e":"Del lat. gingiva.","x":"Las encías le sangraban cada vez que nombraba a su madre."},{"w":"siniestra","d":"Que anuncia desgracia o tiene mala intención; perversa. También, la mano izquierda.","s":["aciaga","funesta","perversa","maléfica","izquierda"],"a":["propicia","benévola","diestra"],"e":"Del lat. sinister, 'izquierdo'.","x":"La casa tenía una quietud siniestra, como si contuviera la respiración."},{"w":"vulgar","d":"Común, ordinario, que carece de distinción; grosero.","s":["ordinario","común","corriente","grosero","chabacano"],"a":["refinado","distinguido","original"],"e":"Del lat. vulgaris, de vulgus, 'pueblo'.","x":"Era una muerte vulgar, de esas que no salen en los diarios; por eso nadie la investigó."},{"w":"doblegar","d":"Obligar a alguien a obedecer; hacer que algo se doble o se curve.","s":["someter","dominar","sojuzgar","vencer","curvar"],"a":["resistir","erguir","enderezar"],"e":"Del lat. duplicare, 'doblar'.","x":"No pudieron doblegar su voluntad, así que doblegaron su cuerpo."},{"w":"campanas","d":"Instrumentos de metal en forma de copa invertida que suenan al ser golpeados por un badajo.","s":["campanillas","esquilas","carillón"],"a":[],"e":"Del lat. tardío campana, por Campania, región famosa por su bronce.","x":"Las campanas sonaron a medianoche, y la iglesia no tenía campanas."},{"w":"delicado","d":"Fino, suave, frágil; que requiere cuidado o tacto.","s":["frágil","fino","sutil","sensible","quebradizo"],"a":["tosco","rudo","resistente"],"e":"Del lat. delicatus.","x":"Tenía un cuello delicado, casi demasiado fácil de quebrar."},{"w":"murciélago","d":"Mamífero volador nocturno, de alas membranosas, que se orienta por ecolocación.","s":["quiróptero","vampiro"],"a":[],"e":"Del lat. mus, muris, 'ratón', y caeculus, 'cieguito'.","x":"El murciélago entró por la ventana y se colgó del velador, mirándola."},{"w":"excrementos","d":"Residuos del alimento que el cuerpo expulsa tras la digestión.","s":["heces","deposiciones","inmundicia","estiércol"],"a":[],"e":"Del lat. excrementum.","x":"Los excrementos del altillo eran humanos, y frescos."},{"w":"angustioso","d":"Que causa angustia o la manifiesta.","s":["agobiante","opresivo","inquietante","desesperante"],"a":["tranquilizador","sereno"],"e":"De angustia, del lat. angustia, 'estrechez'.","x":"Hubo un silencio angustioso antes de que la tapa del cajón empezara a moverse."},{"w":"muriendo","d":"Gerundio de morir: dejar de vivir en ese mismo momento; ir extinguiéndose.","s":["agonizando","expirando","falleciendo","apagándose"],"a":["naciendo","viviendo","reviviendo"],"e":"De morir, del lat. mori.","x":"Estuvo muriendo durante tres días, y en todo ese tiempo nunca cerró los ojos."},{"w":"tinieblas","d":"Falta total de luz; ignorancia o confusión profunda.","s":["oscuridad","sombras","negrura","lobreguez"],"a":["luz","claridad"],"e":"Del lat. tenebrae.","x":"Desde las tinieblas del sótano alguien repetía su nombre con su propia voz."},{"w":"agitado","d":"Que está en movimiento violento o inquieto; nervioso, alterado.","s":["alterado","inquieto","convulso","excitado","turbulento"],"a":["tranquilo","calmo","sereno"],"e":"De agitar, del lat. agitare.","x":"El mar estaba agitado la noche en que el barco volvió sin nadie a bordo."},{"w":"violento","d":"Que actúa con fuerza e ímpetu; que implica uso de la fuerza o causa daño.","s":["brutal","agresivo","impetuoso","feroz","furioso"],"a":["pacífico","manso","suave"],"e":"Del lat. violentus.","x":"Fue un final violento, aunque la víctima parecía dormida."},{"w":"apartar","d":"Separar, alejar o quitar algo o a alguien de un lugar.","s":["alejar","separar","retirar","desviar","aislar"],"a":["acercar","juntar","unir"],"e":"De a- y parte.","x":"Apartó las cortinas y del otro lado la esperaba su reflejo, pero sin ella."},{"w":"espíritu","d":"Ser inmaterial dotado de razón; alma; ánimo o esencia de algo; fantasma.","s":["alma","ánima","fantasma","espectro","esencia"],"a":["cuerpo","materia"],"e":"Del lat. spiritus, 'soplo'.","x":"El espíritu de la casa no quería asustarlos: quería que se quedaran para siempre."},{"w":"trágico","d":"Relativo a la tragedia; desgraciado, funesto, que termina mal.","s":["funesto","desgraciado","fatal","aciago","dramático"],"a":["cómico","feliz","afortunado"],"e":"Del lat. tragicus, del gr. tragikós.","x":"El accidente fue trágico; lo que pasó después en la morgue, inexplicable."},{"w":"comunión","d":"Participación en lo común; en el cristianismo, acto de recibir la eucaristía.","s":["unión","comunidad","eucaristía","afinidad"],"a":["separación","desunión"],"e":"Del lat. communio.","x":"En la primera comunión la hostia se le volvió carne en la boca."},{"w":"imposibilidad","d":"Falta de posibilidad para que algo exista o se haga.","s":["incapacidad","impotencia","inviabilidad"],"a":["posibilidad","facultad"],"e":"De imposible, del lat. impossibilis.","x":"La imposibilidad de gritar era lo peor de la pesadilla, y de la vigilia."},{"w":"aislamiento","d":"Acción de aislar o aislarse; estado de quien está separado de los demás.","s":["soledad","incomunicación","retiro","reclusión","apartamiento"],"a":["compañía","comunicación","integración"],"e":"De aislar, de isla.","x":"Tras años de aislamiento, empezó a contestarles a las voces."},{"w":"poderes","d":"Capacidades o facultades para hacer algo, a veces sobrenaturales; dominio o autoridad.","s":["facultades","dones","fuerzas","dominio","potestades"],"a":["impotencia","debilidad"],"e":"Del lat. vulg. *potere.","x":"Sus poderes aparecieron la noche en que murió la abuela, como una herencia."},{"w":"corromper","d":"Alterar algo y volverlo malo; pudrir; pervertir a alguien.","s":["pudrir","pervertir","depravar","viciar","descomponer"],"a":["purificar","sanear"],"e":"Del lat. corrumpere.","x":"Bastó una semana para que el libro empezara a corromper a toda la familia."},{"w":"habitar","d":"Vivir o morar en un lugar.","s":["morar","residir","ocupar","poblar","vivir"],"a":["abandonar","deshabitar"],"e":"Del lat. habitare.","x":"Algo empezó a habitar en las paredes, y comía cuando ellos dormían."},{"w":"atributos","d":"Cualidades o propiedades propias de un ser; símbolos que identifican a una figura.","s":["cualidades","rasgos","propiedades","características","emblemas"],"a":[],"e":"Del lat. attributum.","x":"Entre los atributos de la santa había un cuchillo y un frasco con ojos."},{"w":"atmósfera","d":"Capa de gases que rodea un astro; ambiente o clima que se percibe en un lugar o situación.","s":["ambiente","clima","aire","entorno"],"a":[],"e":"Del gr. atmós, 'vapor', y sphaîra, 'esfera'.","x":"Había una atmósfera espesa en la casa, como si el aire estuviera de luto."},{"w":"montaña","d":"Gran elevación natural del terreno.","s":["monte","cerro","cordillera","pico","sierra"],"a":["llanura","valle","depresión"],"e":"Del lat. vulg. *montanea.","x":"La montaña devolvía el eco con una voz que no era la de ellos."},{"w":"bestias","d":"Animales cuadrúpedos, sobre todo salvajes; personas brutales o crueles.","s":["fieras","alimañas","monstruos","brutos"],"a":[],"e":"Del lat. bestia.","x":"Las bestias del monte bajaban cuando el pueblo dejaba de rezar."},{"w":"sucias","d":"Que tienen manchas o impurezas; deshonestas o inmorales.","s":["mugrientas","inmundas","manchadas","cochinas","impuras"],"a":["limpias","pulcras","puras"],"e":"De origen incierto, quizá del lat. sucidus, 'jugoso'.","x":"Tenía las uñas sucias de tierra húmeda, y no recordaba haber salido."},{"w":"deforme","d":"Que tiene una forma anormal o desproporcionada.","s":["contrahecho","desfigurado","monstruoso","amorfo","grotesco"],"a":["proporcionado","armonioso","simétrico"],"e":"Del lat. deformis.","x":"La sombra deforme en la pared se movía con un segundo de retraso."},{"w":"chapoteo","d":"Acción de golpear el agua con los pies o las manos; sonido que produce.","s":["salpicadura","borboteo","chapuzón"],"a":[],"e":"De chapotear, onomatopeya.","x":"Se escuchaba un chapoteo en el aljibe tapado desde hacía años."},{"w":"palacio","d":"Edificio grande y lujoso, residencia de reyes o personajes importantes.","s":["alcázar","castillo","mansión","residencia"],"a":["choza","tugurio","rancho"],"e":"Del lat. palatium.","x":"El palacio tenía cuatrocientas habitaciones, y en una seguía la fiesta de 1890."},{"w":"luz","d":"Energía que hace visibles las cosas; claridad; aquello que ilumina o esclarece.","s":["claridad","resplandor","brillo","luminosidad","fulgor"],"a":["oscuridad","tinieblas","sombra"],"e":"Del lat. lux, lucis.","x":"Al final del túnel había una luz, y la luz tenía dientes."},{"w":"magia","d":"Arte de producir efectos sobrenaturales mediante ritos o conjuros; encanto o atractivo misterioso.","s":["hechicería","brujería","ocultismo","encanto","sortilegio"],"a":["realidad","ciencia"],"e":"Del lat. magia, del gr. mageía.","x":"La magia que aprendió de chica tenía un precio, y se lo cobraron de grande."},{"w":"ventana","d":"Abertura en una pared para dar luz y ventilación; posibilidad o acceso a algo.","s":["vano","ventanal","tragaluz","abertura"],"a":[],"e":"Del lat. ventus, 'viento'.","x":"Desde la ventana del tercer piso una nena saludaba, aunque la casa era de una sola planta."},{"w":"símbolo","d":"Imagen, figura u objeto que representa una idea o concepto por convención o asociación.","s":["emblema","signo","señal","alegoría","insignia"],"a":[],"e":"Del lat. symbolus, del gr. sýmbolon.","x":"Pintó el símbolo en la puerta con sangre, y la casa dejó de tener eco."},{"w":"carta","d":"Papel escrito que se envía a alguien para comunicarle algo; naipe.","s":["misiva","epístola","mensaje","naipe"],"a":[],"e":"Del lat. charta, 'papel'.","x":"La carta llegó veinte años después, con la letra de su madre muerta y fecha de mañana."},{"w":"indescifrable","d":"Que no se puede descifrar, entender o interpretar.","s":["ilegible","incomprensible","enigmático","ininteligible"],"a":["descifrable","legible","claro"],"e":"De in- y descifrable, de cifra, del ár. ṣifr.","x":"Las marcas en la piel eran indescifrables, pero cada noche cambiaban."},{"w":"humedad","d":"Presencia de agua o vapor en el aire, en un cuerpo o en un lugar.","s":["mojadura","vaho","rocío","relente"],"a":["sequedad","aridez"],"e":"De húmedo, del lat. humidus.","x":"La humedad dibujaba en la pared el contorno de una persona parada."},{"w":"desfigurado","d":"Que ha perdido su forma o aspecto propio; deformado, especialmente el rostro.","s":["deformado","mutilado","irreconocible","estropeado"],"a":["intacto","íntegro"],"e":"De desfigurar, de des- y figura.","x":"El rostro desfigurado le sonreía desde la vidriera con una sonrisa que reconoció."},{"w":"someter","d":"Imponer la autoridad o el dominio a alguien; exponer algo a una acción.","s":["dominar","doblegar","sojuzgar","subyugar","avasallar"],"a":["liberar","emancipar"],"e":"Del lat. submittere.","x":"Intentaron someterlo con cadenas, pero ellas fueron las que se rompieron primero."},{"w":"demonio","d":"Ser sobrenatural maligno; diablo; persona muy perversa.","s":["diablo","satanás","maligno","íncubo"],"a":["ángel","santo"],"e":"Del lat. daemonium, del gr. daimónion, 'divinidad'.","x":"El demonio no entró por la fuerza: lo invitaron a cenar."},{"w":"combate","d":"Pelea o lucha entre personas, animales o ejércitos.","s":["lucha","batalla","pelea","enfrentamiento","contienda"],"a":["paz","tregua"],"e":"De combatir, del lat. vulg. *combattuere.","x":"Tras el combate, el campo quedó cubierto de cuervos y de gente que no terminaba de morir."},{"w":"revivir","d":"Volver a la vida; recordar algo con intensidad como si se viviera de nuevo.","s":["resucitar","renacer","reanimarse","rememorar"],"a":["morir","olvidar"],"e":"Del lat. revivere.","x":"No quería revivir: quería que los vivos dejaran de llamarlo."},{"w":"enajenado","d":"Que ha perdido la razón o está fuera de sí; también, transmitido a otro.","s":["demente","trastornado","ido","alienado","loco"],"a":["cuerdo","lúcido"],"e":"De enajenar, de en- y ajeno.","x":"El enajenado del asilo dibujaba la misma casa una y otra vez: la tuya."},{"w":"arrancado","d":"Sacado con violencia de su lugar, de raíz.","s":["extirpado","desarraigado","arrebatado","desgarrado"],"a":["plantado","arraigado"],"e":"De arrancar, de origen incierto.","x":"Encontraron el corazón arrancado, todavía latiendo debajo del colchón."},{"w":"hechizo","d":"Práctica o fórmula mágica para influir en alguien; atractivo irresistible.","s":["embrujo","encantamiento","sortilegio","conjuro","maleficio"],"a":["desencanto"],"e":"Del lat. facticius, 'artificial'.","x":"El hechizo funcionó, pero lo que volvió de la tumba no era su marido."},{"w":"alma","d":"Parte inmaterial del ser humano; persona; aquello que da vida o sentido a algo.","s":["espíritu","ánima","esencia","ánimo"],"a":["cuerpo","materia"],"e":"Del lat. anima.","x":"Vendió el alma por una buena cosecha y ahora lo ve en cada espantapájaros."},{"w":"alterado","d":"Que ha sufrido un cambio; perturbado, nervioso o enojado.","s":["perturbado","trastornado","modificado","agitado","nervioso"],"a":["inalterado","sereno","intacto"],"e":"De alterar, del lat. alterare, de alter, 'otro'.","x":"Volvió del bosque con la mirada alterada y una voz que no era la suya."},{"w":"furia","d":"Ira violenta y descontrolada; ímpetu o violencia de algo.","s":["ira","cólera","rabia","saña","frenesí"],"a":["calma","serenidad","mansedumbre"],"e":"Del lat. furia.","x":"La furia del mar dejó en la playa cosas que deberían haber quedado en el fondo."},{"w":"estallar","d":"Reventar de golpe con estruendo; sobrevenir algo violentamente; manifestar bruscamente un sentimiento.","s":["explotar","reventar","detonar","romper","irrumpir"],"a":["contenerse","implosionar"],"e":"De astillar, de astilla.","x":"Las lamparitas empezaron a estallar una por una, en el orden de los dormitorios."},{"w":"hoguera","d":"Fuego hecho con material combustible que levanta mucha llama.","s":["fogata","pira","fuego","lumbre"],"a":[],"e":"De fuego, del lat. focus.","x":"En la hoguera de San Juan alguien vio una cara que gritaba desde las llamas."},{"w":"brujo","d":"Hombre a quien se atribuyen poderes mágicos, por lo general obtenidos de fuerzas oscuras.","s":["hechicero","mago","nigromante","chamán","curandero"],"a":[],"e":"De origen incierto, quizá prerromano.","x":"El brujo del pueblo cobraba en dientes, y no aceptaba de leche."},{"w":"bandurria","d":"Instrumento de cuerda, más pequeño que la guitarra, que se toca con púa; también ave de pico largo y curvo, común en la Patagonia.","s":["laúd","mandolina"],"a":[],"e":"Del lat. tardío pandurium, del gr. pandoûra.","x":"La bandurria graznaba sobre el campo, y donde se posaba, alguien enfermaba."},{"w":"mago","d":"Persona que practica la magia o hace trucos de ilusionismo; sabio de la antigüedad persa.","s":["hechicero","brujo","ilusionista","prestidigitador","nigromante"],"a":[],"e":"Del lat. magus, del gr. mágos, de origen persa.","x":"El mago serruchó a la chica en dos, y nunca supo volver a unirla."},{"w":"poeta desconocido","d":"Autor de poesía cuyo nombre se ignora o que no alcanzó fama.","s":["bardo anónimo","autor anónimo","vate ignoto"],"a":["poeta célebre"],"e":"De poeta (lat. poeta) y desconocido.","x":"En la tumba del poeta desconocido aparecen versos nuevos cada mañana."},{"w":"afilador de cuchillos","d":"Oficio ambulante de quien recorre las calles afilando cuchillos y tijeras, anunciándose con un silbido característico.","s":["amolador","afilador"],"a":[],"e":"De afilar, de filo, y cuchillo, del lat. cultellus.","x":"Se escuchó el silbido del afilador, aunque hacía treinta años que no pasaba nadie.","n":"(silbido)"},{"w":"malevo","d":"En el habla rioplatense, hombre pendenciero y provocador, de vida turbia, que alardea de valiente.","s":["compadre","guapo","matón","pendenciero","cuchillero"],"a":["pacífico","manso"],"e":"Del lat. malevolus, 'malintencionado'.","x":"El malevo bailó con la muerta toda la noche y al amanecer ya no tenía sombra."},{"w":"cuchillero","d":"Hombre hábil en la pelea con cuchillo o que lo usa con frecuencia; también quien fabrica cuchillos.","s":["malevo","matón","pendenciero","navajero"],"a":[],"e":"De cuchillo, del lat. cultellus.","x":"El cuchillero del bajo tenía una cicatriz por cada hombre que había despachado."},{"w":"cataclismo","d":"Catástrofe de grandes proporciones; trastorno grave en la vida social o personal.","s":["desastre","catástrofe","hecatombe","calamidad","debacle"],"a":["bonanza","calma"],"e":"Del lat. cataclysmus, del gr. kataklysmós, 'inundación'.","x":"Después del cataclismo solo quedó en pie la iglesia, y adentro seguían rezando."},{"w":"sonámbula","d":"Persona que camina o actúa mientras duerme.","s":["noctámbula","somnámbula","dormida"],"a":["despierta"],"e":"Del lat. somnus, 'sueño', y ambulare, 'andar'.","x":"La sonámbula bajaba cada noche a la cocina a afilar un cuchillo."},{"w":"ladrón de cuchillos","d":"Imagen insólita: alguien que roba cuchillos, figura inquietante porque se apropia de lo que corta.","s":[],"a":[],"e":"De ladrón (lat. latro) y cuchillo (lat. cultellus).","x":"El ladrón de cuchillos dejaba los cajones vacíos, y después los devolvía uno por uno, de noche."},{"w":"empuñar puñal","d":"Tomar un puñal por el mango con firmeza, con intención de usarlo.","s":["blandir","esgrimir","asir"],"a":["soltar"],"e":"De empuñar (de puño, lat. pugnus) y puñal.","x":"Al empuñar el puñal sintió que ya no era su mano la que lo sostenía.","n":"(que se apoderó de la mano)"},{"w":"hormonas","d":"Sustancias producidas por glándulas que, transportadas por la sangre, regulan funciones del cuerpo.","s":["secreciones"],"a":[],"e":"Del gr. hormôn, 'que excita'.","x":"Las hormonas de la adolescencia le trajeron acné, insomnio y una sed que no era de agua."},{"w":"final abrupto","d":"Desenlace repentino e inesperado, que corta algo de forma brusca.","s":["desenlace súbito","corte brusco"],"a":["final gradual"],"e":"De final (lat. finalis) y abrupto (lat. abruptus).","x":"La historia tuvo un final abrupto, como la cuerda del ahorcado."},{"w":"granada","d":"Fruto de cáscara dura con muchos granos rojos y jugosos; proyectil explosivo que se lanza con la mano.","s":["bomba","explosivo","proyectil"],"a":[],"e":"Del lat. granatum, 'con granos'.","x":"Abrió la granada y los granos parecían dientes de leche bañados en sangre."},{"w":"empuñar","d":"Asir algo por el puño o mango; tomar con la mano cerrada.","s":["asir","agarrar","blandir","esgrimir"],"a":["soltar","dejar"],"e":"De en- y puño.","x":"Volvió a empuñar la pala, aunque el pozo ya tenía la profundidad justa."},{"w":"asomar","d":"Empezar a mostrarse; sacar o mostrar algo por una abertura.","s":["aparecer","surgir","despuntar","mostrar"],"a":["ocultar","esconder"],"e":"De a- y somo, 'lo más alto'.","x":"Algo empezó a asomar por debajo de la puerta del ropero: eran dedos."},{"w":"moscas","d":"Insectos de dos alas, muy comunes, que se posan sobre la comida y la carroña.","s":["dípteros","moscardones"],"a":[],"e":"Del lat. musca.","x":"Las moscas siempre sabían dónde estaba el cuerpo antes que la policía."},{"w":"bichos","d":"Animales pequeños, especialmente insectos; por extensión, criaturas raras o desagradables.","s":["insectos","sabandijas","alimañas","bicharracos"],"a":[],"e":"De origen incierto.","x":"Los bichos salían de la boca del muerto en fila, como si tuvieran un destino."},{"w":"decantar","d":"Separar un líquido de su sedimento vertiéndolo con cuidado; inclinarse por una opción.","s":["trasvasar","separar","inclinarse","optar"],"a":["mezclar"],"e":"Del lat. medieval decanthare.","x":"Decantó el vino despacio, para que el veneno quedara en el fondo de la copa de él."},{"w":"preso","d":"Persona que está en la cárcel o privada de libertad; dominado por algo.","s":["prisionero","recluso","cautivo","encarcelado","reo"],"a":["libre","liberado"],"e":"Del lat. prensus, 'tomado'.","x":"El preso de la celda doce hablaba de noche con alguien que contestaba."},{"w":"autorreferencial","d":"Que se refiere a sí mismo o alude a su propia naturaleza.","s":["reflexivo","ensimismado"],"a":[],"e":"De auto- (gr. autós, 'uno mismo') y referencial.","x":"Era un cuento autorreferencial: el lector moría al llegar al final del cuento."},{"w":"ego","d":"El yo; valoración excesiva de uno mismo.","s":["yo","egocentrismo","vanidad","narcisismo","soberbia"],"a":["humildad","modestia"],"e":"Del lat. ego, 'yo'.","x":"Su ego era tan grande que, muerto, todavía exigía espejos en el ataúd."},{"w":"nostalgia","d":"Tristeza por el recuerdo de un bien perdido, un lugar o un tiempo pasado.","s":["añoranza","melancolía","morriña","evocación"],"a":["olvido","indiferencia"],"e":"Del gr. nóstos, 'regreso', y álgos, 'dolor'.","x":"La nostalgia lo llevó a cavar en el patio de su infancia, y encontró algo creciendo ahí."},{"w":"angustia","d":"Aflicción, congoja o ansiedad intensa; sensación de opresión en el pecho.","s":["congoja","zozobra","aflicción","desasosiego","ansiedad"],"a":["tranquilidad","sosiego","alivio"],"e":"Del lat. angustia, 'estrechez'.","x":"La angustia le apretaba el pecho como una mano que no era imaginaria."},{"w":"hechicero","d":"Persona que practica la hechicería; que cautiva o atrae.","s":["brujo","mago","nigromante","chamán","encantador"],"a":[],"e":"De hechizo, del lat. facticius.","x":"El hechicero le guardó el alma en un frasco de mermelada, y se la mostraba cada tanto."},{"w":"en frasco chico","d":"Del dicho 'los mejores perfumes (y venenos) vienen en frasco chico': lo pequeño puede contener lo más valioso o lo más peligroso.","s":[],"a":[],"e":"Dicho popular.","x":"Le decían enana, hasta que aprendieron que el veneno viene en frasco chico."},{"w":"inesperado","d":"Que sucede sin esperarse ni preverse.","s":["imprevisto","repentino","sorpresivo","súbito","inopinado"],"a":["esperado","previsto","anunciado"],"e":"De in- y esperado.","x":"La visita inesperada tocó el timbre a las tres de la mañana, desde adentro."},{"w":"caída","d":"Acción de caer; descenso brusco; declive o ruina.","s":["desplome","derrumbe","descenso","ruina","decadencia"],"a":["ascenso","subida","auge"],"e":"De caer, del lat. cadere.","x":"La caída duró demasiado para un edificio de cuatro pisos."},{"w":"relojes","d":"Instrumentos que miden y señalan el tiempo.","s":["cronómetros","péndulos","cuadrantes"],"a":[],"e":"Del cat. ant. relotge, del lat. horologium.","x":"Todos los relojes de la casa se detuvieron a las 3:17, la hora en que ella murió."},{"w":"cascarudo","d":"En el Río de la Plata, insecto coleóptero de caparazón duro; escarabajo.","s":["escarabajo","coleóptero","bicho"],"a":[],"e":"De cáscara.","x":"El cascarudo salió de la oreja del muerto y se fue caminando tranquilo."},{"w":"confusión","d":"Falta de claridad u orden; desconcierto o turbación mental.","s":["desconcierto","caos","desorden","perplejidad","embrollo"],"a":["claridad","orden","lucidez"],"e":"Del lat. confusio.","x":"En la confusión del incendio nadie notó que salió uno más de los que habían entrado."},{"w":"maldición gitana","d":"Imprecación atribuida a la tradición gitana, considerada en el folclore especialmente poderosa e inevitable.","s":["maleficio","mal de ojo","anatema","hechizo"],"a":["bendición"],"e":"De maldición (lat. maledictio) y gitano, de egiptano.","x":"La maldición tardó tres generaciones en cumplirse, pero se cumplió."},{"w":"tormenta","d":"Perturbación atmosférica violenta con viento, lluvia, truenos y relámpagos; agitación intensa.","s":["tempestad","temporal","borrasca","vendaval","tromba"],"a":["calma","bonanza"],"e":"Del lat. tormenta, pl. de tormentum.","x":"Con cada relámpago de la tormenta, la figura del jardín estaba más cerca."},{"w":"te envuelve","d":"Del verbo envolver: te rodea o te cubre por completo; te atrapa en una situación o sensación.","s":["te rodea","te cubre","te abraza","te atrapa"],"a":["te libera","te suelta"],"e":"Del lat. involvere.","x":"Primero la niebla te envuelve, después te olvida, y después ya no estás."},{"w":"déspota","d":"Persona que gobierna o trata a los demás con poder absoluto y arbitrario.","s":["tirano","dictador","autócrata","opresor"],"a":["justo","benévolo"],"e":"Del gr. despótēs, 'amo'.","x":"El déspota hizo enterrar a sus enemigos de pie, para que siguieran mirándolo."},{"w":"estruendo","d":"Ruido grande y estrepitoso.","s":["estrépito","fragor","retumbo","bramido"],"a":["silencio","susurro"],"e":"Del lat. vulg. *extonitus, 'atronado'.","x":"Un estruendo sacudió la casa, y después se oyó a alguien reír en el sótano."},{"w":"agujas","d":"Barras finas y puntiagudas de metal para coser o inyectar; manecillas del reloj.","s":["alfileres","punzones","manecillas"],"a":[],"e":"Del lat. vulg. *acucula, diminutivo de acus.","x":"Tenía agujas clavadas en la muñeca de trapo, y él sentía cada una."},{"w":"luna","d":"Satélite natural de la Tierra; su luz.","s":["selene","satélite"],"a":["sol"],"e":"Del lat. luna.","x":"La luna llena salió roja, y los perros dejaron de ladrar todos al mismo tiempo."},{"w":"podredumbre","d":"Putrefacción, descomposición; corrupción moral.","s":["putrefacción","descomposición","corrupción","carroña"],"a":["frescura","pureza"],"e":"De podre, del lat. putrem.","x":"La podredumbre empezaba por debajo de las uñas."},{"w":"oscuridad","d":"Falta de luz; falta de claridad para entender algo.","s":["tinieblas","sombras","negrura","penumbra"],"a":["luz","claridad"],"e":"De oscuro, del lat. obscurus.","x":"En la oscuridad alguien le sostenía la mano, y vivía solo."},{"w":"carromato","d":"Carro grande de dos ruedas, cubierto con toldo, típico de feriantes y circos ambulantes.","s":["carreta","carro","carricoche","diligencia"],"a":[],"e":"Del it. carromatto.","x":"El carromato del circo llegó de noche, y al irse faltaban los chicos del pueblo."},{"w":"enmohecido","d":"Cubierto de moho; oxidado o deteriorado por el tiempo o la falta de uso.","s":["mohoso","oxidado","herrumbroso","podrido","añejo"],"a":["nuevo","limpio"],"e":"De enmohecer, de moho.","x":"El pan enmohecido de la mesa estaba ahí desde el día del velorio."},{"w":"hurón","d":"Mamífero carnívoro pequeño y alargado, usado para cazar conejos; persona huraña o que todo lo husmea.","s":["turón","husmeador","huraño"],"a":[],"e":"Del lat. vulg. *furo, 'ladrón'.","x":"El hurón se metió en la cueva y salió con algo en la boca que no era un conejo."},{"w":"tripas","d":"Intestinos; vísceras; parte interior de algo.","s":["intestinos","entrañas","vísceras","menudos"],"a":[],"e":"De origen incierto.","x":"Las tripas le crujían de hambre, aunque había comido algo que gritaba."},{"w":"intrincado","d":"Enredado, complicado, de difícil comprensión o recorrido. También se acepta la forma intricado.","s":["enrevesado","enmarañado","complicado","laberíntico","intricado"],"a":["sencillo","simple","claro"],"e":"Del lat. intricare, 'enredar'.","x":"El bosque era tan intrincado que los árboles parecían cambiar de lugar."},{"w":"obsceno","d":"Que ofende al pudor; indecente o grotesco hasta lo repulsivo.","s":["indecente","impúdico","procaz","lascivo","grosero"],"a":["decente","pudoroso","casto"],"e":"Del lat. obscenus, 'de mal agüero'.","x":"Había algo obsceno en la forma en que el cadáver sonreía."},{"w":"precario","d":"De poca estabilidad o duración; que carece de los medios necesarios.","s":["inestable","frágil","endeble","inseguro","deficiente"],"a":["estable","sólido","seguro"],"e":"Del lat. precarius, 'obtenido por ruego'.","x":"La escalera era precaria, y del sótano subía un olor dulce."},{"w":"agazapado","d":"Encogido y pegado al suelo para ocultarse o esperar para atacar.","s":["acurrucado","escondido","encogido","emboscado"],"a":["erguido","expuesto"],"e":"De agazapar, de gazapo.","x":"Algo estaba agazapado detrás de la heladera, esperando que apagaran la luz."},{"w":"garra","d":"Mano o pata de un animal con uñas fuertes, curvas y afiladas; fuerza, empuje.","s":["zarpa","uña","ímpetu"],"a":[],"e":"Quizá del árabe hispánico.","x":"La garra salió del colchón y le rozó el tobillo."},{"w":"poro","d":"Orificio diminuto de la piel o de cualquier superficie.","s":["orificio","agujero","intersticio"],"a":[],"e":"Del lat. porus, del gr. póros, 'paso'.","x":"De cada poro le brotaba una gota de tinta negra."},{"w":"cangrejos","d":"Crustáceos de caparazón duro, con pinzas, que caminan de costado.","s":["crustáceos","jaibas","centollas"],"a":[],"e":"De cangro, del lat. cancer.","x":"Los cangrejos subieron a la playa con anillos y dientes de oro entre las pinzas."},{"w":"viento","d":"Corriente de aire que se mueve de forma natural en la atmósfera.","s":["aire","brisa","ventarrón","ráfaga","vendaval"],"a":["calma","quietud"],"e":"Del lat. ventus.","x":"El viento patagónico traía voces de gente que se había perdido en la estepa."},{"w":"roer","d":"Desgastar algo con los dientes poco a poco; atormentar o consumir interiormente.","s":["carcomer","mordisquear","corroer","desgastar"],"a":[],"e":"Del lat. rodere.","x":"Por la noche se escuchaba algo roer el interior del ataúd."},{"w":"circular","d":"Que tiene forma de círculo; moverse en círculo o de un lugar a otro.","s":["redondo","rotar","transitar","girar"],"a":["recto","lineal","detenerse"],"e":"Del lat. circularis.","x":"Las marcas en el campo eran circulares, y el pasto del centro estaba quemado."},{"w":"madrugada","d":"Momento del día que precede al amanecer; tiempo entre la medianoche y el alba.","s":["alba","amanecer","aurora","albor"],"a":["anochecer","ocaso","crepúsculo"],"e":"De madrugar, del lat. vulg. *maturicare.","x":"En la madrugada, los muertos del pueblo salen a mirar las casas que eran suyas."},{"w":"el hambre de palabras","d":"Necesidad intensa de nombrar, leer o escribir; deseo voraz de lenguaje.","s":["avidez verbal","ansia de palabras"],"a":["silencio","saciedad"],"e":"De hambre (lat. famen) y palabra (lat. parabola).","x":"El hambre de palabras lo mantenía despierto, y a veces le comía la lengua."},{"w":"placebo","d":"Sustancia sin efecto terapéutico que se administra como si lo tuviera, con efecto psicológico.","s":["simulación","engaño","paliativo"],"a":["remedio","cura"],"e":"Del lat. placebo, 'agradaré'.","x":"Le dieron un placebo y mejoró, y eso asustó más a los médicos."},{"w":"tragedia","d":"Obra dramática de final funesto; suceso fatal y desgraciado.","s":["desgracia","catástrofe","drama","infortunio","calamidad"],"a":["comedia","dicha"],"e":"Del lat. tragoedia, del gr. tragōidía.","x":"La tragedia pasó en la casa de enfrente, pero los gritos vinieron de la nuestra."},{"w":"desconcierto","d":"Estado de confusión o perplejidad; desorden.","s":["perplejidad","confusión","turbación","desorientación","caos"],"a":["orden","serenidad","claridad"],"e":"De desconcertar, de des- y concierto.","x":"Hubo desconcierto en la morgue cuando el cuerpo pidió agua."},{"w":"exceso","d":"Lo que sobrepasa la medida o lo razonable.","s":["demasía","abuso","desmesura","sobrante","desenfreno"],"a":["carencia","mesura","moderación"],"e":"Del lat. excessus.","x":"Murió de un exceso de todo, pero sobre todo de curiosidad."},{"w":"dorado","d":"De color de oro o parecido; feliz, esplendoroso.","s":["áureo","brillante","rubio"],"a":["plateado","opaco"],"e":"De dorar, del lat. deaurare.","x":"El diente dorado del muerto era lo único que brillaba en el cajón."},{"w":"mendigo","d":"Persona que pide limosna para vivir.","s":["pordiosero","indigente","pedigüeño","menesteroso","linyera"],"a":["rico","acaudalado"],"e":"De mendigar, del lat. mendicare.","x":"El mendigo de la esquina sabía tu nombre y la hora exacta en que ibas a morir."},{"w":"pitonisa","d":"Adivina o sacerdotisa que vaticinaba el futuro; vidente.","s":["adivina","sibila","profetisa","vidente","oráculo"],"a":[],"e":"Del lat. pythonissa, de Pitón, la serpiente de Delfos.","x":"La pitonisa leyó su mano, palideció, y le devolvió la plata."},{"w":"oráculo","d":"Respuesta de una divinidad a través de un intermediario; lugar o persona que predice el futuro.","s":["profecía","vaticinio","augurio","adivino","pitonisa"],"a":[],"e":"Del lat. oraculum.","x":"El oráculo habló con la voz de su hijo muerto."},{"w":"lluvia","d":"Agua que cae de las nubes en forma de gotas.","s":["precipitación","aguacero","chaparrón","llovizna","diluvio"],"a":["sequía","sequedad"],"e":"Del lat. pluvia.","x":"Después de la lluvia, la tierra del cementerio quedó llena de huellas que salían, no que entraban."},{"w":"aladas","d":"Que tienen alas o son ligeras como si las tuvieran.","s":["voladoras","aéreas","ligeras","etéreas"],"a":["ápteras","pesadas"],"e":"De ala, del lat. ala.","x":"Criaturas aladas golpeaban el vidrio toda la noche, buscando la luz de la cuna."},{"w":"némesis","d":"Enemigo o rival implacable; venganza o castigo justo e inevitable.","s":["enemigo","rival","adversario","venganza","castigo"],"a":["aliado","amigo"],"e":"Del gr. Némesis, diosa de la venganza.","x":"Su némesis lo esperó cuarenta años en el mismo sillón."},{"w":"podar","d":"Cortar las ramas superfluas de los árboles y plantas.","s":["cortar","talar","recortar","desmochar"],"a":[],"e":"Del lat. putare.","x":"Mientras podaba el rosal, encontró entre las raíces un anillo con el dedo adentro."},{"w":"desgarrar","d":"Rasgar, romper algo tirando de él con fuerza; causar mucho dolor.","s":["rasgar","despedazar","descuartizar","lacerar","rajar"],"a":["coser","unir","remendar"],"e":"De des- y garra.","x":"Lo que sea que vivía en el bosque desgarraba las ovejas sin comerlas."},{"w":"cornisa","d":"Saliente que corona un edificio o una pared; borde estrecho de un precipicio.","s":["saliente","borde","alero","moldura"],"a":[],"e":"Del it. cornice.","x":"En la cornisa del campanario había alguien sentado cada noche, mirando al pueblo."},{"w":"machete","d":"Cuchillo grande y pesado, de hoja ancha, usado para cortar caña o abrirse paso en la maleza.","s":["cuchillo","facón","alfanje"],"a":[],"e":"De macho, 'mazo'.","x":"El machete colgaba en el galpón con la hoja todavía húmeda."},{"w":"dios pagano","d":"Divinidad de una religión politeísta o anterior al cristianismo.","s":["deidad antigua","ídolo","numen"],"a":[],"e":"De dios (lat. deus) y pagano (lat. paganus, 'aldeano').","x":"Le dejaban ofrendas al dios pagano del monte, y cuando dejaron de hacerlo, empezó a bajar él."},{"w":"ceguera","d":"Privación total de la vista; ofuscación que impide ver con claridad.","s":["invidencia","ofuscación","obcecación"],"a":["visión","lucidez"],"e":"De ciego, del lat. caecus.","x":"La ceguera le llegó de golpe, justo cuando empezó a ver a los otros."},{"w":"cupido","d":"Dios romano del amor, representado como un niño alado con arco y flechas; hombre enamoradizo.","s":["eros","amor"],"a":[],"e":"Del lat. Cupido, 'deseo'.","x":"La flecha de cupido le atravesó el corazón de verdad, y nadie supo de dónde salió."},{"w":"nido","d":"Refugio que hacen las aves para poner sus huevos; lugar donde se agrupan o esconden personas o cosas.","s":["guarida","madriguera","refugio","cobijo"],"a":[],"e":"Del lat. nidus.","x":"En el nido había tres huevos, y uno latía como un corazón humano."},{"w":"ráfaga","d":"Golpe violento y breve de viento; serie rápida de disparos o destellos.","s":["racha","soplo","golpe","ventarrón"],"a":["calma"],"e":"De origen incierto.","x":"Una ráfaga apagó todas las velas, y cuando las volvieron a prender eran uno más en la mesa."},{"w":"inenarrable","d":"Que no se puede narrar o explicar con palabras.","s":["indescriptible","inefable","indecible","inexplicable"],"a":["narrable","descriptible"],"e":"Del lat. inenarrabilis.","x":"Lo que vio en el sótano era inenarrable, así que lo dibujó, y el dibujo se movía."},{"w":"catástrofe","d":"Suceso desdichado que produce gran destrucción; desenlace de una tragedia.","s":["desastre","cataclismo","hecatombe","calamidad"],"a":["bonanza","fortuna"],"e":"Del gr. katastrophḗ, 'trastorno'.","x":"La catástrofe dejó al pueblo bajo el agua, pero las campanas siguieron sonando."},{"w":"fantasma","d":"Imagen de una persona muerta que se aparece a los vivos; ilusión o figura imaginaria.","s":["espectro","aparición","espíritu","ánima","aparecido"],"a":[],"e":"Del lat. phantasma, del gr. phántasma, 'aparición'.","x":"El fantasma no sabía que estaba muerto, y creía que nosotros éramos los intrusos."},{"w":"sutil","d":"Delicado, tenue, fino; agudo e ingenioso.","s":["tenue","fino","delicado","leve","perspicaz"],"a":["burdo","grosero","evidente"],"e":"Del lat. subtilis.","x":"Había un olor sutil a almendras en el té de la abuela."},{"w":"sufrimiento","d":"Padecimiento, dolor o pena.","s":["padecimiento","dolor","tormento","aflicción","martirio"],"a":["placer","gozo","alivio"],"e":"De sufrir, del lat. sufferre.","x":"El sufrimiento del pueblo alimentaba algo que vivía bajo la plaza."},{"w":"fascinación","d":"Atracción irresistible; engaño o alucinación.","s":["atracción","hechizo","embeleso","seducción","encanto"],"a":["repulsión","aversión","rechazo"],"e":"Del lat. fascinatio, 'encantamiento'.","x":"Su fascinación por los cementerios empezó el día que vio a la abuela sentada sobre su propia tumba."},{"w":"suicidio","d":"Acción de quitarse la vida voluntariamente; por extensión, conducta que daña gravemente a quien la realiza.","s":["autoeliminación","inmolación"],"a":[],"e":"Del lat. sui, 'de sí mismo', y -cidio, 'matar'.","x":"En el pueblo nadie hablaba del suicidio del farero, pero todos dejaban flores en la escollera."},{"w":"desesperado","d":"Que ha perdido la esperanza; furioso, extremo.","s":["desesperanzado","angustiado","abatido","frenético"],"a":["esperanzado","tranquilo","optimista"],"e":"De desesperar, de des- y esperar.","x":"Arañaba la tapa del cajón con un ritmo desesperado, y nadie en el velorio lo escuchaba."},{"w":"obsesión","d":"Idea, deseo o preocupación que se impone en la mente de forma persistente.","s":["manía","fijación","obstinación","idea fija"],"a":["indiferencia","desinterés"],"e":"Del lat. obsessio, 'asedio'.","x":"Su obsesión eran los ojos: los coleccionaba en frascos ordenados por color."},{"w":"envejecido","d":"Que se ha hecho viejo o parece más viejo de lo que es.","s":["avejentado","ajado","marchito","gastado","añejo"],"a":["rejuvenecido","joven","lozano"],"e":"De envejecer, de viejo.","x":"Salió del sótano envejecido veinte años en una noche."},{"w":"doblez","d":"Parte que se dobla o pliega; falsedad, hipocresía en el obrar.","s":["pliegue","hipocresía","falsedad","duplicidad"],"a":["sinceridad","franqueza"],"e":"De doble, del lat. duplus.","x":"En cada doblez de la carta había escondida una uña."},{"w":"desvanecido","d":"Que se ha disipado o desaparecido gradualmente; que perdió el sentido.","s":["esfumado","disipado","difuminado","desmayado"],"a":["nítido","presente","consciente"],"e":"De desvanecer, del lat. evanescere.","x":"El retrato estaba desvanecido, salvo los ojos, que se veían cada vez más nítidos."},{"w":"sortilegio","d":"Adivinación por suertes supersticiosas; hechizo o embrujo.","s":["hechizo","conjuro","embrujo","maleficio","encantamiento"],"a":[],"e":"Del lat. sortilegus, 'adivino'.","x":"El sortilegio estaba escrito en el dorso del espejo."},{"w":"resquebrajado","d":"Que tiene grietas o hendiduras superficiales.","s":["agrietado","cuarteado","rajado","fisurado"],"a":["intacto","liso","entero"],"e":"De resquebrajar, de quebrar.","x":"El espejo resquebrajado mostraba un reflejo distinto en cada pedazo."},{"w":"gases venenosos","d":"Sustancias gaseosas tóxicas que pueden dañar o matar al ser respiradas.","s":["gases tóxicos","vapores letales","miasmas"],"a":["aire puro"],"e":"De gas (voz creada por van Helmont) y venenoso, de veneno.","x":"Del pozo subían gases venenosos, y una canción."},{"w":"fétido","d":"Que despide un olor muy desagradable.","s":["hediondo","pestilente","maloliente","apestoso","nauseabundo"],"a":["aromático","fragante","perfumado"],"e":"Del lat. foetidus.","x":"El aliento fétido le rozó la nuca aunque estaba sola en el ascensor."},{"w":"inyectado","d":"Introducido por medio de una inyección; dicho de los ojos, enrojecidos por la sangre.","s":["enrojecido","congestionado","introducido"],"a":[],"e":"De inyectar, del lat. iniectare.","x":"Tenía los ojos inyectados en sangre y sonreía sin parpadear."},{"w":"inmundicia","d":"Suciedad, basura; impureza moral.","s":["basura","mugre","porquería","suciedad"],"a":["limpieza","pureza","higiene"],"e":"Del lat. immunditia.","x":"Vivía entre la inmundicia, y algo en la inmundicia vivía con él."},{"w":"nauseabundo","d":"Que produce náuseas por su mal olor o aspecto.","s":["repugnante","asqueroso","fétido","repulsivo","hediondo"],"a":["agradable","apetitoso"],"e":"Del lat. nauseabundus.","x":"Un olor nauseabundo salía del freezer que nadie se animaba a abrir."},{"w":"pegajoso","d":"Que se pega con facilidad; empalagoso o molesto por insistente.","s":["viscoso","adherente","gomoso","pringoso"],"a":["seco","liso"],"e":"De pegar, del lat. picare, 'untar con pez'.","x":"Las paredes del túnel eran pegajosas, y tibias."},{"w":"subterráneo","d":"Que está debajo de la tierra.","s":["soterrado","profundo","oculto","enterrado"],"a":["superficial","aéreo"],"e":"Del lat. subterraneus.","x":"El río subterráneo arrastraba cosas que pedían ayuda."},{"w":"insólito","d":"Raro, extraño, nunca visto.","s":["inusitado","extraordinario","inaudito","raro","extraño"],"a":["habitual","común","frecuente"],"e":"Del lat. insolitus.","x":"Lo insólito no era que los muertos caminaran, sino que pagaran el boleto."},{"w":"monstruoso","d":"Contrario al orden natural; enorme o extraordinariamente feo o cruel.","s":["horrendo","espantoso","deforme","atroz","colosal"],"a":["bello","normal","bondadoso"],"e":"Del lat. monstruosus.","x":"El bebé era monstruoso, pero su madre lo arrullaba con una ternura más monstruosa aún."},{"w":"magullado","d":"Que tiene contusiones o golpes sin herida abierta.","s":["contuso","amoratado","golpeado","lastimado"],"a":["ileso","intacto"],"e":"De magullar, del lat. maculare, 'manchar'.","x":"Despertó magullado, con huellas de dedos en los tobillos."},{"w":"espantoso","d":"Que causa espanto; horrible, muy feo o desagradable.","s":["horrible","aterrador","terrorífico","horrendo","pavoroso"],"a":["hermoso","agradable"],"e":"De espanto, de espantar, del lat. vulg. *expaventare.","x":"Fue un grito espantoso, y lo peor es que salió de su propia boca."},{"w":"abandonado","d":"Dejado solo, sin cuidado ni atención; descuidado.","s":["desamparado","desierto","deshabitado","olvidado","descuidado"],"a":["cuidado","habitado","acompañado"],"e":"De abandonar, del fr. abandonner.","x":"En el hospital abandonado las camillas seguían tibias."},{"w":"sabiduría","d":"Conocimiento profundo; prudencia en el obrar.","s":["saber","conocimiento","erudición","prudencia","sensatez"],"a":["ignorancia","necedad"],"e":"De sabio, del lat. sapidus.","x":"La sabiduría que le dio el libro venía con una voz que no se callaba nunca."},{"w":"amargura","d":"Sabor amargo; aflicción, disgusto, resentimiento.","s":["aflicción","pesadumbre","desconsuelo","resentimiento","hiel"],"a":["dulzura","alegría","satisfacción"],"e":"De amargo, del lat. amarus.","x":"La amargura de la vieja se volvió veneno, y lo puso en el té."},{"w":"frustración","d":"Sentimiento de decepción al no conseguir lo que se desea.","s":["decepción","desilusión","fracaso","desengaño"],"a":["satisfacción","logro","éxito"],"e":"Del lat. frustratio.","x":"La frustración del espíritu se notaba en los platos que se rompían solos."},{"w":"sistemático","d":"Que sigue un sistema o método; que procede con orden riguroso.","s":["metódico","ordenado","riguroso","organizado"],"a":["desordenado","caótico","asistemático"],"e":"Del lat. systematicus.","x":"Mataba de forma sistemática, siempre un martes, siempre con lluvia."},{"w":"paradoja","d":"Idea o hecho que parece contradictorio o absurdo pero puede encerrar una verdad.","s":["contradicción","absurdo","contrasentido","antinomia"],"a":["lógica","coherencia"],"e":"Del lat. paradoxa, del gr. parádoxa, 'contrario a la opinión'.","x":"La paradoja del fantasma: tenía miedo de los vivos."},{"w":"brutal","d":"Cruel, violento, propio de un bruto; enorme o tremendo.","s":["salvaje","cruel","bestial","feroz","atroz"],"a":["delicado","suave","humano"],"e":"De bruto, del lat. brutus.","x":"El golpe fue brutal, pero lo que más le dolió fue que viniera de ella."},{"w":"envoltura","d":"Lo que cubre o envuelve algo exteriormente.","s":["envoltorio","cubierta","funda","capa","corteza"],"a":["contenido","interior"],"e":"De envolver.","x":"La envoltura del regalo estaba manchada, y desde adentro se oía respirar."},{"w":"errabundo","d":"Que va de un lugar a otro sin rumbo fijo.","s":["errante","vagabundo","nómada","trotamundos"],"a":["sedentario","estable"],"e":"Del lat. errabundus.","x":"El espíritu errabundo de la estepa se sube a los autos que paran de noche."},{"w":"pavonea","d":"Del verbo pavonearse: hacer ostentación vanidosa de sí mismo.","s":["presume","alardea","ostenta","se jacta"],"a":["se humilla","se esconde"],"e":"De pavón, 'pavo real', del lat. pavo.","x":"La muerte se pavonea por el baile con un vestido que reconocen todas las viudas."},{"w":"macerado","d":"Ablandado al dejarlo sumergido en un líquido; dicho de la piel, arrugada y blanda por la humedad.","s":["empapado","remojado","ablandado","adobado"],"a":["seco"],"e":"De macerar, del lat. macerare.","x":"Las manos del ahogado estaban maceradas, pero seguían apretando algo."},{"w":"carne","d":"Parte blanda del cuerpo de los animales y del ser humano; alimento animal.","s":["músculo","chicha","tejido","cuerpo"],"a":["espíritu","alma"],"e":"Del lat. caro, carnis.","x":"La carne no se pudría en esa heladera, y nadie sabía de quién era."},{"w":"Patagonia","d":"Región del extremo sur de América, compartida por Argentina y Chile, de estepas, viento y costa.","s":["estepa patagónica","sur"],"a":[],"e":"Probablemente del nombre patagón que Magallanes dio a sus habitantes.","x":"En la Patagonia el viento borra las huellas, pero no las de todos."},{"w":"existencia","d":"Acto de existir; vida humana.","s":["vida","ser","realidad","presencia"],"a":["inexistencia","muerte","nada"],"e":"Del lat. exsistentia.","x":"Su existencia era un rumor en el pueblo hasta que alguien vio sus huellas."},{"w":"descubierto","d":"Que no está cubierto o tapado; hallado o revelado.","s":["destapado","expuesto","revelado","hallado"],"a":["cubierto","oculto","tapado"],"e":"De descubrir, del lat. discooperire.","x":"El secreto quedó descubierto cuando el perro trajo una mano al umbral."},{"w":"seres","d":"Entes, criaturas o personas que existen.","s":["criaturas","entes","individuos","entidades"],"a":[],"e":"De ser, del lat. esse.","x":"Seres sin rostro caminaban en fila por la banquina de la ruta."},{"w":"sal","d":"Sustancia blanca y cristalina que sirve para condimentar y conservar; gracia o ingenio.","s":["cloruro de sodio","gracia","salero"],"a":[],"e":"Del lat. sal.","x":"Tiraron sal en el umbral y algo del otro lado aulló toda la noche."},{"w":"chorreando","d":"Gerundio de chorrear: cayendo un líquido en chorro o goteando abundantemente.","s":["goteando","escurriendo","manando","derramando"],"a":[],"e":"De chorro, de origen onomatopéyico.","x":"Entró chorreando agua del río, aunque se había ahogado hacía diez años."},{"w":"degollar","d":"Cortar la garganta o el cuello de una persona o animal.","s":["decapitar","descabezar","acuchillar"],"a":[],"e":"Del lat. decollare.","x":"Degollar al cordero era parte del ritual, pero esa vez el cordero habló."},{"w":"tsunami","d":"Ola gigantesca provocada por un terremoto o erupción submarina.","s":["maremoto","ola gigante"],"a":["calma"],"e":"Del japonés tsunami, 'ola de puerto'.","x":"Después del tsunami la playa quedó cubierta de relojes detenidos a la misma hora."},{"w":"cicatrices","d":"Señales que quedan en la piel después de cerrarse una herida.","s":["marcas","costurones","señales","huellas"],"a":[],"e":"Del lat. cicatrix, -icis.","x":"Sus cicatrices formaban un mapa, y el mapa llevaba a una tumba."},{"w":"acuchillar","d":"Herir o matar con un cuchillo o arma blanca.","s":["apuñalar","herir","rajar"],"a":[],"e":"De cuchillo.","x":"Lo acuchillaron trece veces, y en el juicio declaró él mismo."},{"w":"embestidas","d":"Ataques o arremetidas violentas.","s":["acometidas","arremetidas","ataques","asaltos"],"a":["retiradas"],"e":"De embestir, del it. investire.","x":"Las embestidas contra la puerta duraron toda la noche, desde adentro del ropero."},{"w":"pena","d":"Sentimiento de tristeza; castigo impuesto por una falta.","s":["tristeza","pesar","aflicción","castigo","condena"],"a":["alegría","premio"],"e":"Del lat. poena.","x":"Le daba pena enterrarlo, así que lo dejó sentado a la mesa."},{"w":"frío","d":"Temperatura baja; falta de afecto o emoción.","s":["helado","gélido","glacial","indiferente"],"a":["calor","cálido","afectuoso"],"e":"Del lat. frigidus.","x":"Sintió un frío en la espalda, como una mano que lo empujaba hacia la ventana."},{"w":"yugulares","d":"Venas principales del cuello que llevan la sangre de la cabeza al corazón.","s":["venas del cuello"],"a":[],"e":"Del lat. iugulum, 'garganta'.","x":"Tenía la marca de dos dientes justo sobre la yugular."},{"w":"cimiento","d":"Base sobre la que se apoya un edificio; fundamento o principio de algo.","s":["base","fundamento","basamento","origen"],"a":["techo","cúspide"],"e":"Del lat. caementum.","x":"En el cimiento de la iglesia encontraron huesos de chicos, ordenados por tamaño."},{"w":"huesos","d":"Piezas duras que forman el esqueleto de los vertebrados.","s":["osamenta","esqueleto","restos"],"a":["carne"],"e":"Del lat. ossum.","x":"Los huesos de la cripta amanecían acomodados de otra forma cada día."},{"w":"cianuro","d":"Compuesto químico extremadamente venenoso, con olor a almendras amargas.","s":["veneno","tósigo","ponzoña"],"a":["antídoto"],"e":"Del gr. kyanós, 'azul oscuro'.","x":"Las galletitas de la tía olían a almendra, y no llevaban almendras."},{"w":"cicuta","d":"Planta venenosa de flores blancas; veneno extraído de ella, célebre por la muerte de Sócrates.","s":["veneno","ponzoña","tósigo"],"a":["antídoto"],"e":"Del lat. cicuta.","x":"Le sirvió la cicuta en la taza de porcelana de la abuela."},{"w":"sarcoma","d":"Tumor maligno que se origina en tejidos conectivos como hueso, músculo o grasa.","s":["tumor","neoplasia","cáncer"],"a":[],"e":"Del gr. sárkōma, 'excrecencia carnosa'.","x":"El sarcoma crecía, y en las radiografías tenía forma de mano."},{"w":"leucemia","d":"Cáncer de la sangre caracterizado por la proliferación anormal de glóbulos blancos.","s":["cáncer de sangre"],"a":[],"e":"Del gr. leukós, 'blanco', y haîma, 'sangre'.","x":"El médico habló de leucemia; la abuela habló de otra cosa que se le había metido en la sangre."},{"w":"macabra","d":"Que participa de lo feo y repulsivo de la muerte.","s":["fúnebre","lúgubre","tétrica","siniestra","mortuoria"],"a":["alegre","festiva"],"e":"Del fr. macabre, quizá de danse Macabré.","x":"Tenía una colección macabra de muñecas hechas con pelo de los vecinos."},{"w":"mugre","d":"Suciedad grasienta.","s":["suciedad","roña","grasa","porquería","inmundicia"],"a":["limpieza","pulcritud"],"e":"Del lat. mucor, 'moho'.","x":"Debajo de la mugre de la ventana alguien había escrito \"ayuda\" desde afuera."},{"w":"ejecutar","d":"Llevar a cabo una acción; dar muerte a un condenado.","s":["realizar","efectuar","ajusticiar","fusilar"],"a":["indultar","omitir"],"e":"Del lat. exsecutus.","x":"Lo iban a ejecutar al amanecer, pero el amanecer nunca llegó."},{"w":"calcinar","d":"Quemar completamente algo hasta reducirlo a cenizas o carbón.","s":["carbonizar","abrasar","incinerar","quemar"],"a":[],"e":"Del lat. calx, calcis, 'cal'.","x":"El fuego llegó a calcinar la casa entera, menos la cuna."},{"w":"garrotazos","d":"Golpes dados con un garrote o palo grueso.","s":["palazos","bastonazos","porrazos","golpes"],"a":["caricias"],"e":"De garrote, quizá del fr. garrot.","x":"Lo echaron del pueblo a garrotazos, y volvió esa noche con todos sus muertos."},{"w":"aullar","d":"Emitir aullidos el lobo, el perro u otros animales; gritar de dolor o furia.","s":["ulular","gañir","bramar","gemir","gritar"],"a":["callar"],"e":"Del lat. ululare.","x":"Los perros empezaron a aullar mirando la misma ventana vacía."},{"w":"un rostro sin ojos","d":"Imagen de una cara a la que le faltan los ojos; símbolo de lo inhumano, lo ciego o lo que mira sin ver.","s":["cara vacía","rostro ciego"],"a":[],"e":"Imagen poética.","x":"Desde el fondo del espejo lo miraba un rostro sin ojos, y aun así lo veía."},{"w":"cara agujero","d":"Imagen de un rostro reducido a un hueco, sin facciones; lo que debería ser cara y es vacío.","s":["rostro hueco","cara vacía"],"a":[],"e":"Imagen poética.","x":"Tenía cara agujero, y del agujero salía viento."},{"w":"enterrado bajo un árbol","d":"Imagen de algo o alguien sepultado entre las raíces de un árbol, oculto y alimentando su crecimiento.","s":["sepultado","soterrado","inhumado"],"a":["exhumado","desenterrado"],"e":"De enterrar (de tierra) y árbol (lat. arbor).","x":"El limonero daba los frutos más grandes del barrio, y nadie preguntaba por el marido."},{"w":"silencio","d":"Ausencia de ruido o de palabras.","s":["mutismo","mudez","quietud","sigilo","calma"],"a":["ruido","estruendo","bullicio"],"e":"Del lat. silentium.","x":"Lo que asustó fue el silencio repentino de los grillos."},{"w":"marchito","d":"Que ha perdido la frescura, el vigor o la lozanía.","s":["mustio","ajado","seco","lánguido","apagado"],"a":["lozano","fresco","florido"],"e":"Quizá del lat. marcidus.","x":"Dejó un ramo marchito en su propia tumba."},{"w":"ira","d":"Enojo muy violento.","s":["furia","cólera","rabia","enojo","saña"],"a":["calma","serenidad","paciencia"],"e":"Del lat. ira.","x":"La ira del espíritu hacía hervir el agua de los floreros."},{"w":"estertor","d":"Respiración ronca y anhelosa propia de los moribundos.","s":["agonía","ronquido","jadeo","boqueada"],"a":[],"e":"Del lat. stertere, 'roncar'.","x":"El estertor duró toda la noche, y a la mañana seguía saliendo de la habitación vacía.","r":1},{"w":"mortaja","d":"Vestidura, sábana o lienzo con que se envuelve un cadáver para enterrarlo.","s":["sudario","lienzo","sábana","paño"],"a":[],"e":"De origen discutido, vinculado a muerte.","x":"Cosía su propia mortaja de noche, con hilo que sacaba de su pelo.","r":1},{"w":"sudario","d":"Lienzo con que se cubre el rostro o el cuerpo de un difunto.","s":["mortaja","lienzo","velo","paño"],"a":[],"e":"Del lat. sudarium, 'pañuelo para el sudor'.","x":"Bajo el sudario, la boca seguía moviéndose.","r":1},{"w":"exhumar","d":"Desenterrar un cadáver o restos humanos; sacar a la luz algo olvidado.","s":["desenterrar","excavar","rescatar"],"a":["inhumar","enterrar","sepultar"],"e":"Del lat. ex, 'fuera de', y humus, 'tierra'.","x":"Cuando fueron a exhumar el cuerpo, el cajón estaba arañado por dentro.","r":1},{"w":"cripta","d":"Lugar subterráneo, generalmente bajo una iglesia, donde se entierra a los muertos.","s":["bóveda","panteón","sepulcro","catacumba"],"a":[],"e":"Del lat. crypta, del gr. krýptē, 'escondida'.","x":"En la cripta había una silla, y siempre estaba tibia.","r":1},{"w":"osario","d":"Lugar donde se depositan los huesos sacados de las sepulturas.","s":["huesera","cripta","catacumba"],"a":[],"e":"Del lat. ossarium, de os, ossis, 'hueso'.","x":"En el osario los cráneos estaban todos mirando hacia la puerta.","r":1},{"w":"nigromancia","d":"Práctica de adivinar el futuro o invocar a los muertos; magia negra.","s":["necromancia","hechicería","magia negra","brujería"],"a":[],"e":"Del lat. tardío nigromantia, del gr. nekromanteía.","x":"Aprendió nigromancia con un libro sin título que le dejó su padre.","r":1},{"w":"aquelarre","d":"Reunión nocturna de brujas, a veces con la presencia del demonio.","s":["sabbat","conciliábulo"],"a":[],"e":"Del vasco akelarre, 'prado del macho cabrío'.","x":"El aquelarre se hacía en el claro del bosque, y esa noche faltaba la maestra del pueblo.","r":1},{"w":"ponzoña","d":"Sustancia venenosa; aquello que es nocivo o corrompe.","s":["veneno","tósigo","toxina","maldad"],"a":["antídoto"],"e":"Del lat. potio, -onis, 'bebida'.","x":"Había ponzoña en sus palabras y en el licor que servía.","r":1},{"w":"putrefacto","d":"Podrido, corrompido.","s":["podrido","descompuesto","corrupto","hediondo"],"a":["fresco","sano"],"e":"Del lat. putrefactus.","x":"El olor putrefacto venía de la heladera, que llevaba meses desenchufada.","r":1},{"w":"lívido","d":"Amoratado; intensamente pálido.","s":["amoratado","cárdeno","pálido","cadavérico"],"a":["sonrosado","rubicundo"],"e":"Del lat. lividus.","x":"Tenía la cara lívida, pero la sonrisa intacta.","r":1},{"w":"miasma","d":"Efluvio maligno que se desprende de cuerpos enfermos o materias corruptas.","s":["efluvio","emanación","hedor","vaho"],"a":["aroma"],"e":"Del gr. míasma, 'mancha'.","x":"Un miasma salía del pantano y la gente del pueblo soñaba lo mismo.","r":1},{"w":"lóbrego","d":"Oscuro, tenebroso; triste, melancólico.","s":["tenebroso","sombrío","oscuro","lúgubre"],"a":["luminoso","alegre"],"e":"Quizá del lat. lubricus, 'resbaladizo'.","x":"El pasillo lóbrego terminaba en una puerta que nadie recordaba haber visto.","r":1},{"w":"umbrío","d":"Que tiene sombra o poca luz.","s":["sombrío","sombreado","oscuro","umbroso"],"a":["soleado","luminoso"],"e":"Del lat. umbra, 'sombra'.","x":"En el rincón umbrío del jardín no crecía nada, salvo una mano.","r":1},{"w":"tétrico","d":"Muy triste, grave, melancólico; que evoca la muerte.","s":["lúgubre","fúnebre","sombrío","macabro"],"a":["alegre","jovial"],"e":"Del lat. taetricus.","x":"La casa tenía un aire tétrico incluso a mediodía.","r":1},{"w":"lúgubre","d":"Triste, fúnebre, sombrío.","s":["fúnebre","tétrico","sombrío","mortecino"],"a":["alegre","festivo"],"e":"Del lat. lugubris.","x":"Un canto lúgubre subía del pozo cada viernes.","r":1},{"w":"sepulcro","d":"Obra que se construye para dar sepultura a uno o más cadáveres.","s":["tumba","sepultura","mausoleo","panteón"],"a":["cuna"],"e":"Del lat. sepulcrum.","x":"El sepulcro estaba vacío, pero había polvo fresco en la entrada.","r":1},{"w":"catafalco","d":"Túmulo suntuoso que se levanta para las exequias de un difunto.","s":["túmulo","capilla ardiente"],"a":[],"e":"Del it. catafalco.","x":"Sobre el catafalco, el muerto giró la cabeza hacia la viuda.","r":1},{"w":"réquiem","d":"Misa o composición musical por los difuntos.","s":["misa de difuntos","responso","elegía"],"a":[],"e":"Del lat. requiem, 'descanso'.","x":"La orquesta tocaba un réquiem, y en el escenario había un cajón abierto.","r":1},{"w":"plañidera","d":"Mujer a quien se pagaba por llorar en los entierros.","s":["llorona","lloradora"],"a":[],"e":"De plañir, del lat. plangere.","x":"La plañidera lloraba lágrimas negras, y cobraba por adelantado.","r":1},{"w":"letanía","d":"Oración formada por una serie de invocaciones; lista larga y monótona.","s":["rogativa","plegaria","salmodia","retahíla"],"a":[],"e":"Del lat. litania, del gr. litaneía, 'súplica'.","x":"Repetía una letanía en voz baja, y cada vez cambiaba una palabra.","r":1},{"w":"penumbra","d":"Sombra débil entre la luz y la oscuridad.","s":["media luz","semioscuridad","sombra"],"a":["claridad","resplandor"],"e":"Del lat. paene, 'casi', y umbra, 'sombra'.","x":"En la penumbra del cuarto, el ropero tenía la puerta entreabierta.","r":1},{"w":"crepúsculo","d":"Claridad que hay al amanecer y, sobre todo, al anochecer; decadencia.","s":["ocaso","atardecer","anochecer","declive"],"a":["alba","auge"],"e":"Del lat. crepusculum.","x":"En el crepúsculo, los árboles del cementerio parecían personas paradas.","r":1},{"w":"ultratumba","d":"Ámbito más allá de la muerte.","s":["más allá","otro mundo","inframundo"],"a":[],"e":"De ultra-, 'más allá', y tumba.","x":"Una voz de ultratumba le dictaba números de lotería.","r":1},{"w":"espectro","d":"Figura fantasmal y horrible; persona muy delgada y demacrada.","s":["fantasma","aparición","ánima","sombra"],"a":[],"e":"Del lat. spectrum, 'imagen'.","x":"El espectro aparecía en todas las fotos familiares, detrás del abuelo.","r":1},{"w":"ánima","d":"Alma, especialmente la que pena en el purgatorio.","s":["alma","espíritu","sombra"],"a":["cuerpo"],"e":"Del lat. anima.","x":"Las ánimas del purgatorio golpeaban las ventanas en noviembre.","r":1},{"w":"íncubo","d":"Demonio que, según la tradición medieval, visita a las durmientes por la noche; pesadilla opresiva.","s":["demonio","pesadilla","súcubo"],"a":[],"e":"Del lat. incubus, 'que se acuesta encima'.","x":"Despertaba agotada, con la sensación de que el íncubo había pasado la noche sentado sobre su pecho.","r":1},{"w":"gárgola","d":"Caño o canal, a menudo con forma de figura monstruosa, por donde se vierte el agua de los tejados.","s":["caño","canalón","quimera"],"a":[],"e":"Del fr. gargouille.","x":"La gárgola del campanario ya no estaba en su lugar cuando amaneció.","r":1},{"w":"engendro","d":"Criatura deforme o monstruosa; obra mal concebida.","s":["monstruo","adefesio","aberración","aborto"],"a":["belleza"],"e":"De engendrar, del lat. ingenerare.","x":"El engendro de la cuna no lloraba: se reía.","r":1},{"w":"aberración","d":"Desvío de lo que se considera normal o lícito; error grave.","s":["anomalía","monstruosidad","perversión","desviación"],"a":["normalidad","acierto"],"e":"Del lat. aberratio.","x":"Lo que salió del huevo era una aberración, y tenía la voz de su madre.","r":1},{"w":"sanguinolento","d":"Que echa sangre o está mezclado con ella.","s":["sangriento","ensangrentado","sangrante"],"a":[],"e":"Del lat. sanguinolentus.","x":"Escupió algo sanguinolento que tenía forma de llave.","r":1},{"w":"coágulo","d":"Masa espesa que se forma al coagularse un líquido, en especial la sangre.","s":["grumo","cuajarón","trombo"],"a":[],"e":"Del lat. coagulum.","x":"En el fondo de la bañadera quedó un coágulo con forma de corazón pequeño.","r":1},{"w":"vísceras","d":"Órganos contenidos en las cavidades del cuerpo.","s":["entrañas","tripas","órganos","menudos"],"a":[],"e":"Del lat. viscera.","x":"Leía el futuro en las vísceras de las gallinas, y una vez leyó el suyo.","r":1},{"w":"entrañas","d":"Vísceras; lo más íntimo o profundo de algo.","s":["vísceras","tripas","interior","profundidades"],"a":["superficie"],"e":"Del lat. interanea.","x":"Desde las entrañas de la montaña llegaba un latido.","r":1},{"w":"tuétano","d":"Médula de los huesos; lo más profundo de algo.","s":["médula","meollo","esencia"],"a":["superficie"],"e":"De origen incierto.","x":"El frío se le metió hasta el tuétano, y desde ahí empezó a hablarle.","r":1},{"w":"carroña","d":"Carne descompuesta de animales muertos.","s":["despojos","restos","podredumbre"],"a":[],"e":"Del lat. vulg. *caronia, de caro, 'carne'.","x":"Los caranchos se juntaban sobre la carroña, pero esa no terminaba de morir.","r":1},{"w":"sanguijuela","d":"Gusano que chupa sangre; persona que se aprovecha de otra.","s":["parásito","chupasangre","aprovechador"],"a":[],"e":"Del lat. sanguisuga.","x":"Le pusieron sanguijuelas para sacarle el mal, y todas murieron.","r":1},{"w":"alimaña","d":"Animal dañino, especialmente el que ataca a la caza o al ganado.","s":["bicho","sabandija","fiera","plaga"],"a":[],"e":"Del lat. animalia.","x":"Alguna alimaña rondaba el gallinero, una que sabía abrir las trancas.","r":1},{"w":"belladona","d":"Planta venenosa de bayas negras, usada antiguamente para dilatar las pupilas.","s":["veneno"],"a":[],"e":"Del it. belladonna, 'mujer hermosa'.","x":"Se ponía belladona en los ojos para verse hermosa en su propio velorio.","r":1},{"w":"mandrágora","d":"Planta de raíz con forma vagamente humana, a la que se atribuían poderes mágicos y un grito mortal al arrancarla.","s":[],"a":[],"e":"Del lat. mandragoras, del gr. mandragóras.","x":"Arrancó la mandrágora con los oídos tapados con cera, y aun así escuchó algo.","r":1},{"w":"acónito","d":"Planta de flores azules muy venenosa, asociada en el folclore a lobos y brujas.","s":["matalobos","veneno"],"a":[],"e":"Del lat. aconitum, del gr. akóniton.","x":"Plantaba acónito alrededor de la casa, y los lobos no se acercaban; otras cosas sí.","r":1},{"w":"láudano","d":"Preparado de opio, usado antiguamente como calmante.","s":["opiáceo","calmante","narcótico"],"a":["estimulante"],"e":"Del lat. medieval laudanum.","x":"Tomaba láudano para no soñar con la cosa del sótano, pero la cosa subía igual.","r":1},{"w":"gangrena","d":"Muerte de un tejido por falta de riego sanguíneo o por infección.","s":["necrosis","putrefacción"],"a":[],"e":"Del lat. gangraena, del gr. gángraina.","x":"La gangrena le subía por el brazo como una enredadera negra.","r":1},{"w":"necrosis","d":"Muerte de las células o tejidos de un organismo.","s":["gangrena","mortificación"],"a":["regeneración"],"e":"Del gr. nékrōsis, 'mortificación'.","x":"La necrosis le dibujó en la espalda la forma de dos alas.","r":1},{"w":"pústula","d":"Vejiga inflamada de la piel, llena de pus.","s":["absceso","llaga","ampolla","grano"],"a":[],"e":"Del lat. pustula.","x":"De la pústula salió una araña diminuta.","r":1},{"w":"supurar","d":"Formar o expulsar pus una herida.","s":["segregar","exudar","rezumar"],"a":["cicatrizar"],"e":"Del lat. suppurare.","x":"La herida no paraba de supurar, y el líquido olía a rosas.","r":1},{"w":"hedor","d":"Olor muy desagradable y penetrante.","s":["pestilencia","fetidez","peste","tufo"],"a":["aroma","fragancia"],"e":"Del lat. foetor.","x":"El hedor llegó antes que el visitante.","r":1},{"w":"herrumbre","d":"Óxido del hierro.","s":["óxido","orín","moho"],"a":[],"e":"Del lat. ferrumen.","x":"La reja tenía herrumbre, y entre la herrumbre, pelos.","r":1},{"w":"carcoma","d":"Insecto que roe la madera; preocupación que consume lentamente.","s":["polilla","termita","desgaste","inquietud"],"a":[],"e":"De origen incierto.","x":"La carcoma había vaciado el ataúd, pero no lo que guardaba.","r":1},{"w":"rescoldo","d":"Brasa menuda que queda bajo la ceniza; resto de un sentimiento.","s":["brasa","ascua","ceniza","remanente"],"a":[],"e":"De origen incierto.","x":"Entre los rescoldos de la hoguera, algo seguía respirando.","r":1},{"w":"pira","d":"Hoguera en la que se quemaban cadáveres o víctimas de sacrificios.","s":["hoguera","fogata","pira funeraria"],"a":[],"e":"Del lat. pyra, del gr. pyrá.","x":"Lo subieron a la pira y las llamas se apartaron de él.","r":1},{"w":"cilicio","d":"Faja de cerdas o con puntas metálicas que se lleva ceñida al cuerpo como penitencia.","s":["penitencia","mortificación"],"a":[],"e":"Del lat. cilicium.","x":"Llevaba un cilicio bajo el hábito, y nunca dejaba de sonreír.","r":1},{"w":"relicario","d":"Lugar o caja donde se guardan reliquias; medallón para llevar un recuerdo.","s":["cofre","medallón","urna"],"a":[],"e":"De reliquia, del lat. reliquiae, 'restos'.","x":"En el relicario no había un mechón de pelo, sino un diente.","r":1},{"w":"exvoto","d":"Ofrenda que se cuelga en una iglesia en agradecimiento por un favor recibido, a menudo con forma de parte del cuerpo.","s":["ofrenda","promesa"],"a":[],"e":"Del lat. ex voto, 'por promesa'.","x":"Entre los exvotos de cera había una pierna que goteaba sangre de verdad.","r":1},{"w":"sacrilegio","d":"Profanación de algo sagrado.","s":["profanación","blasfemia","herejía","impiedad"],"a":["veneración","piedad"],"e":"Del lat. sacrilegium.","x":"Cometieron sacrilegio en la capilla, y desde entonces la virgen llora hacia adentro.","r":1},{"w":"profanar","d":"Tratar algo sagrado sin respeto; deshonrar.","s":["violar","mancillar","deshonrar","degradar"],"a":["venerar","honrar","respetar"],"e":"Del lat. profanare.","x":"Al profanar la tumba se llevaron el anillo, pero algo se llevó a uno de ellos.","r":1},{"w":"conjuro","d":"Fórmula mágica para invocar o alejar fuerzas sobrenaturales.","s":["sortilegio","hechizo","ensalmo","invocación","exorcismo"],"a":[],"e":"De conjurar, del lat. coniurare.","x":"Pronunció mal una palabra del conjuro, y lo que vino no era lo que esperaba.","r":1},{"w":"maleficio","d":"Daño causado por arte de hechicería; hechizo maligno.","s":["hechizo","embrujo","mal de ojo","sortilegio"],"a":["bendición"],"e":"Del lat. maleficium.","x":"El maleficio le secaba la piel, de afuera hacia adentro.","r":1},{"w":"ensalmo","d":"Modo supersticioso de curar con oraciones y recetas mágicas.","s":["conjuro","oración","sortilegio"],"a":[],"e":"De en- y salmo.","x":"La curandera recitó un ensalmo y la fiebre pasó a la nena del vecino.","r":1},{"w":"presagio","d":"Señal que anuncia un suceso, por lo general malo.","s":["augurio","agüero","anuncio","premonición"],"a":[],"e":"Del lat. praesagium.","x":"Tres cuervos en el alambrado eran un mal presagio; doce, una certeza.","r":1},{"w":"agorero","d":"Que predice males o desgracias.","s":["pájaro de mal agüero","pesimista","cenizo","adivino"],"a":["optimista"],"e":"De agüero, del lat. augurium.","x":"El agorero del pueblo anunció la muerte, y nadie le creyó hasta que se cumplió con él.","r":1},{"w":"ominoso","d":"Que anuncia algo malo; abominable.","s":["siniestro","amenazador","funesto","aciago"],"a":["propicio","favorable"],"e":"Del lat. ominosus.","x":"Hubo un silencio ominoso cuando abrieron la puerta del cuarto de servicio.","r":1},{"w":"aciago","d":"Infausto, de mal agüero.","s":["funesto","nefasto","desgraciado","infausto"],"a":["afortunado","dichoso"],"e":"Del lat. aegyptiacus (dies), 'día egipcio', considerado nefasto.","x":"Ese día aciago murieron los tres, a la misma hora y en lugares distintos.","r":1},{"w":"funesto","d":"Que causa desgracia o la anuncia.","s":["aciago","nefasto","desgraciado","fatídico"],"a":["feliz","venturoso"],"e":"Del lat. funestus.","x":"Fue una noche funesta, de esas que el pueblo prefiere no nombrar.","r":1},{"w":"inexorable","d":"Que no se deja vencer por ruegos; que no se puede evitar.","s":["implacable","inevitable","inflexible","fatal"],"a":["evitable","compasivo"],"e":"Del lat. inexorabilis.","x":"La marea subía, inexorable, y el pozo con el chico adentro estaba en la playa.","r":1},{"w":"zozobra","d":"Inquietud, aflicción, angustia.","s":["inquietud","desasosiego","angustia","ansiedad"],"a":["tranquilidad","sosiego"],"e":"De zozobrar, del cat. sotsobre.","x":"Vivía en una zozobra constante desde que encontró las huellas en el techo.","r":1},{"w":"desasosiego","d":"Falta de sosiego; intranquilidad.","s":["inquietud","zozobra","ansiedad","intranquilidad"],"a":["sosiego","calma"],"e":"De des- y sosiego.","x":"Un desasosiego le subía cada vez que pasaba frente al espejo del pasillo.","r":1},{"w":"congoja","d":"Angustia y aflicción del ánimo.","s":["angustia","pena","aflicción","desconsuelo"],"a":["alivio","consuelo"],"e":"Del cat. congoixa.","x":"Con una congoja enorme le cerró los ojos, y él los volvió a abrir.","r":1},{"w":"quebranto","d":"Gran pérdida o daño; aflicción, dolor profundo.","s":["pérdida","daño","aflicción","desaliento"],"a":["ganancia","alivio"],"e":"De quebrantar.","x":"El quebranto de la familia fue tan grande que la casa empezó a resquebrajarse.","r":1},{"w":"desvarío","d":"Dicho o hecho fuera de razón; delirio.","s":["delirio","desatino","locura","extravío"],"a":["cordura","sensatez"],"e":"De desvariar.","x":"En su desvarío decía que la casa tenía hambre; tenía razón.","r":1},{"w":"febril","d":"Que tiene fiebre; ardoroso, desasosegado.","s":["afiebrado","calenturiento","frenético","ardoroso"],"a":["tranquilo","sosegado"],"e":"Del lat. febrilis.","x":"En su sueño febril veía a su madre muerta cocinando.","r":1},{"w":"macilento","d":"Flaco, descolorido, triste.","s":["demacrado","pálido","mustio","enjuto"],"a":["lozano","rozagante"],"e":"Del lat. macilentus.","x":"Una figura macilenta aparecía en la ventana del hospital cerrado.","r":1},{"w":"cetrino","d":"De color amarillo verdoso; melancólico.","s":["amarillento","aceitunado","verdoso"],"a":["sonrosado"],"e":"Del lat. citrinus, 'color de limón'.","x":"Tenía la piel cetrina de los que llevan años sin ver el sol.","r":1},{"w":"famélico","d":"Hambriento; muy delgado por falta de alimento.","s":["hambriento","desnutrido","esquelético","escuálido"],"a":["saciado","rollizo"],"e":"Del lat. famelicus.","x":"Los perros famélicos rondaban el cementerio después de la lluvia.","r":1},{"w":"andrajoso","d":"Cubierto de andrajos.","s":["harapiento","haraposo","desastrado"],"a":["elegante","atildado"],"e":"De andrajo, de origen incierto.","x":"Un nene andrajoso pedía en la estación, y no se reflejaba en las vidrieras.","r":1},{"w":"tullido","d":"Que ha perdido el movimiento del cuerpo o de algún miembro.","s":["lisiado","impedido","baldado"],"a":["ágil","sano"],"e":"De tullir, del lat. tollere.","x":"El tullido de la plaza bailaba solo cuando no había nadie.","r":1},{"w":"mazmorra","d":"Prisión subterránea.","s":["calabozo","celda","cárcel"],"a":[],"e":"Del ár. hisp. maṭmúra, 'silo'.","x":"En la mazmorra contaban los días por las uñas que les crecían.","r":1},{"w":"grillete","d":"Arco de hierro que asegura una cadena al tobillo de un preso.","s":["cadena","argolla","grillo"],"a":["libertad"],"e":"De grillo, 'cepo'.","x":"Al levantar el piso encontraron un grillete, todavía cerrado sobre un hueso.","r":1},{"w":"patíbulo","d":"Tablado donde se ejecuta la pena de muerte.","s":["cadalso","horca","tablado"],"a":[],"e":"Del lat. patibulum.","x":"Desde el patíbulo, el condenado señaló a alguien en la multitud, que murió esa noche.","r":1},{"w":"cadalso","d":"Tablado que se levanta para la ejecución de la pena de muerte.","s":["patíbulo","horca","tarima"],"a":[],"e":"Del lat. vulg. *catafalicum.","x":"El cadalso crujía aunque nadie lo pisara.","r":1},{"w":"verdugo","d":"Ejecutor de la pena de muerte; persona cruel.","s":["ejecutor","ajusticiador","torturador"],"a":["víctima"],"e":"De verde, por la vara de castigo.","x":"El verdugo se sacó la capucha, y tenía la cara del condenado.","r":1},{"w":"fauces","d":"Parte posterior de la boca de los mamíferos; boca de una fiera.","s":["boca","garganta","hocico","quijadas"],"a":[],"e":"Del lat. fauces.","x":"Las fauces del perro se cerraron sobre la nada, y la nada gritó.","r":1},{"w":"colmillo","d":"Diente agudo y fuerte situado entre los incisivos y las muelas.","s":["canino","diente"],"a":[],"e":"Del lat. columella, 'columnita'.","x":"Le encontraron un colmillo clavado en el hombro, y no era de animal.","r":1},{"w":"acechar","d":"Observar o esperar cautelosamente con algún propósito, a menudo hostil.","s":["espiar","vigilar","atisbar","observar"],"a":["descuidar","ignorar"],"e":"Del lat. assectari, 'seguir'.","x":"Algo acechaba desde el maizal, paciente como una estación.","r":1},{"w":"merodear","d":"Vagar por las inmediaciones de un lugar, generalmente con malos fines.","s":["rondar","vagar","husmear"],"a":[],"e":"De merodeador, del fr. maraudeur.","x":"Algo merodeaba la casa, y por el sonido, tenía demasiadas patas.","r":1},{"w":"reptar","d":"Andar arrastrándose como los reptiles.","s":["arrastrarse","serpentear","deslizarse"],"a":["erguirse","caminar"],"e":"Del lat. reptare.","x":"Escuchó algo reptar por el cielorraso, de un cuarto a otro.","r":1},{"w":"desollar","d":"Quitar la piel a un animal o persona; criticar con dureza.","s":["despellejar","cuerear","pelar"],"a":[],"e":"Del lat. vulg. *exfollare.","x":"Desollaba conejos con una canción de cuna en los labios.","r":1},{"w":"lacerar","d":"Lastimar, herir, desgarrar el cuerpo; afligir.","s":["herir","desgarrar","lastimar","magullar"],"a":["curar","sanar"],"e":"Del lat. lacerare.","x":"Las espinas le laceraban las manos, pero no podía dejar de arrancar las rosas.","r":1},{"w":"socavón","d":"Hueco que se produce por hundimiento del suelo; cueva excavada en una ladera.","s":["hoyo","cavidad","galería","hundimiento"],"a":[],"e":"De socavar.","x":"En el socavón de la mina abandonada todavía se escuchan picos golpeando.","r":1},{"w":"noctámbulo","d":"Que anda de noche o tiene hábitos nocturnos.","s":["nocherniego","trasnochador","nocturno"],"a":["madrugador","diurno"],"e":"Del lat. nox, noctis, y ambulare, 'andar'.","x":"El noctámbulo del barrio nunca proyectaba sombra bajo los faroles.","r":1},{"w":"insomne","d":"Que no duerme; desvelado.","s":["desvelado","despierto","trasnochado"],"a":["dormido","adormecido"],"e":"Del lat. insomnis.","x":"Las noches insomnes le enseñaron a reconocer los pasos de la casa.","r":1},{"w":"vahído","d":"Desvanecimiento o mareo breve.","s":["desmayo","mareo","vértigo","síncope"],"a":[],"e":"De vaho.","x":"Un vahído la tiró al piso, y cuando se levantó ya no estaba sola.","r":1},{"w":"vesania","d":"Demencia, locura furiosa.","s":["locura","demencia","furia","insania"],"a":["cordura","sensatez"],"e":"Del lat. vesania.","x":"Lo encontraron en plena vesania, pintando las paredes con lo que tenía a mano.","r":1},{"w":"abyecto","d":"Despreciable, vil en extremo.","s":["vil","ruin","despreciable","rastrero","infame"],"a":["noble","digno"],"e":"Del lat. abiectus, 'arrojado'.","x":"Fue un crimen abyecto, y el pueblo entero lo encubrió.","r":1},{"w":"acíbar","d":"Jugo amargo del áloe; amargura, sinsabor.","s":["amargura","hiel","áloe","disgusto"],"a":["dulzura","miel"],"e":"Del ár. hisp. aṣṣíbr.","x":"Cada recuerdo de ella le sabía a acíbar.","r":1},{"w":"esperpento","d":"Persona o cosa notable por su fealdad o aspecto grotesco; género literario que deforma la realidad.","s":["adefesio","mamarracho","engendro"],"a":["belleza","primor"],"e":"De origen incierto.","x":"El esperpento del espejo imitaba sus gestos con medio segundo de demora.","r":1},{"w":"umbral","d":"Parte inferior de la puerta; principio o límite de algo.","s":["entrada","quicio","límite","comienzo"],"a":["salida","final"],"e":"Del lat. liminaris.","x":"Nunca cruzaba el umbral sin permiso, pero siempre encontraba quién se lo diera.","r":1},{"w":"taciturno","d":"Callado, silencioso; triste, melancólico.","s":["callado","silencioso","huraño","melancólico","sombrío"],"a":["locuaz","alegre","comunicativo"],"e":"Del lat. taciturnus.","x":"El taciturno del fondo del bar nunca pedía nada, y nunca se iba.","r":1}];
